window.DD_FULL = window.DD_FULL || {}; window.DD_FULL["alevel-1"] = {"questions":[{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"e","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation at a university library loan desk.\n\nStudent: Hi, I'd like to renew these two books, please. They're both due tomorrow.\nLibrarian: Let me check... (1) ______ Someone has placed a hold on the history book, so it has to come back by the due date.\nStudent: Oh no. I still need it for my term paper. Is there any way around that?\nLibrarian: (2) ______ You could scan the chapters you need before you return it. The copy room is on the second floor, and you're allowed up to ten per cent of a book.\nStudent: That should work. And the other one?\nLibrarian: That's renewed until the 28th. Just remember that the late fines went up this semester — it's twenty baht a day now.\nStudent: (3) ______ I'd better set a reminder on my phone, then.","stem":"Which choice best completes gap (1)?","choices":["I'm afraid the library is closed tomorrow.","You've already paid the fines on both of them.","The economics book is fine, but I can't renew the other one.","Both books have been renewed for another two weeks."],"answer":2,"explanation":{"en":"The librarian goes on to explain that the history book has a hold on it, so only one book can be renewed: 'The economics book is fine, but I can't renew the other one.' The other replies contradict what follows.","th":"บรรณารักษ์อธิบายต่อว่าหนังสือประวัติศาสตร์มีคนจองไว้ จึงต่ออายุได้เพียงเล่มเดียว คำตอบที่ถูกคือ 'The economics book is fine, but I can't renew the other one.' ส่วนคำตอบอื่นขัดกับข้อความที่ตามมา"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation at a university library loan desk.\n\nStudent: Hi, I'd like to renew these two books, please. They're both due tomorrow.\nLibrarian: Let me check... (1) ______ Someone has placed a hold on the history book, so it has to come back by the due date.\nStudent: Oh no. I still need it for my term paper. Is there any way around that?\nLibrarian: (2) ______ You could scan the chapters you need before you return it. The copy room is on the second floor, and you're allowed up to ten per cent of a book.\nStudent: That should work. And the other one?\nLibrarian: That's renewed until the 28th. Just remember that the late fines went up this semester — it's twenty baht a day now.\nStudent: (3) ______ I'd better set a reminder on my phone, then.","stem":"Which choice best completes gap (2)?","choices":["That's not really my problem, is it?","Not for that copy, I'm afraid, but there is another option.","Sure, you can keep it for as long as you need.","Of course — I'll cancel the other person's hold for you."],"answer":1,"explanation":{"en":"The librarian cannot break the hold but offers an alternative (scanning chapters), so 'Not for that copy, I'm afraid, but there is another option.' fits. Cancelling someone else's hold or letting the student keep the book contradicts the rule, and 'That's not really my problem' is rude for a service desk.","th":"บรรณารักษ์ยกเลิกการจองของคนอื่นไม่ได้ แต่เสนอทางเลือกอื่น (สแกนบางบท) จึงต้องใช้ 'Not for that copy, I'm afraid, but there is another option.' การยกเลิกการจองหรือให้ยืมต่อได้ขัดกับกฎ ส่วน 'That's not really my problem' ไม่สุภาพสำหรับผู้ให้บริการ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation at a university library loan desk.\n\nStudent: Hi, I'd like to renew these two books, please. They're both due tomorrow.\nLibrarian: Let me check... (1) ______ Someone has placed a hold on the history book, so it has to come back by the due date.\nStudent: Oh no. I still need it for my term paper. Is there any way around that?\nLibrarian: (2) ______ You could scan the chapters you need before you return it. The copy room is on the second floor, and you're allowed up to ten per cent of a book.\nStudent: That should work. And the other one?\nLibrarian: That's renewed until the 28th. Just remember that the late fines went up this semester — it's twenty baht a day now.\nStudent: (3) ______ I'd better set a reminder on my phone, then.","stem":"Which choice best completes gap (3)?","choices":["Never mind, it's only a few baht.","Congratulations on the new system.","Twenty? That's quite a jump.","That's a relief to hear."],"answer":2,"explanation":{"en":"The student is surprised by the higher fine and decides to set a reminder, so 'Twenty? That's quite a jump.' fits. A higher fine is not 'a relief', 'Congratulations' does not suit the situation, and 'it's only a few baht' would not lead to setting a reminder.","th":"นักศึกษาตกใจที่ค่าปรับขึ้นและตัดสินใจตั้งการเตือนในโทรศัพท์ จึงตอบ 'Twenty? That's quite a jump.' ค่าปรับที่สูงขึ้นไม่ใช่เรื่องน่าโล่งใจ คำแสดงความยินดีไม่เข้ากับสถานการณ์ และถ้าคิดว่าเป็นเงินเล็กน้อยก็ไม่ต้องตั้งการเตือน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation at a university library loan desk.\n\nStudent: Hi, I'd like to renew these two books, please. They're both due tomorrow.\nLibrarian: Let me check... (1) ______ Someone has placed a hold on the history book, so it has to come back by the due date.\nStudent: Oh no. I still need it for my term paper. Is there any way around that?\nLibrarian: (2) ______ You could scan the chapters you need before you return it. The copy room is on the second floor, and you're allowed up to ten per cent of a book.\nStudent: That should work. And the other one?\nLibrarian: That's renewed until the 28th. Just remember that the late fines went up this semester — it's twenty baht a day now.\nStudent: (3) ______ I'd better set a reminder on my phone, then.","stem":"What will the student most likely do before returning the history book?","choices":["Ask the other borrower to wait a week","Copy the chapters needed for the term paper","Renew it again online","Pay a fine of twenty baht"],"answer":1,"explanation":{"en":"The student says 'That should work' after the librarian suggests scanning the chapters, so the student will copy the chapters needed for the term paper. The book is not late yet, and it cannot be renewed because of the hold.","th":"นักศึกษาตอบว่า 'That should work' หลังจากบรรณารักษ์แนะนำให้สแกนบทที่ต้องใช้ จึงน่าจะถ่ายสำเนาบทที่ต้องใช้ทำรายงาน หนังสือยังไม่เกินกำหนดจึงไม่ต้องเสียค่าปรับ และต่ออายุไม่ได้เพราะมีคนจอง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"e","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Workplace conversation","th":"บทสนทนาในที่ทำงาน"},"passage":"Read the conversation between a manager and an intern at a marketing company.\n\nMs Lee: Nattapong, have you got a minute? It's about the market report.\nNattapong: Sure. Is something wrong with it?\nMs Lee: Not wrong exactly. The data's solid, but the summary runs to three pages. The directors won't read past the first paragraph.\nNattapong: (5) ______\nMs Lee: Exactly. Lead with the two or three findings that really matter, and put the detail in an appendix.\nNattapong: Got it. When do you need the revised version?\nMs Lee: Thursday would be ideal, but (6) ______ if you need to check the figures again.\nNattapong: Thursday should be fine. Would you mind looking over the new summary before I send it out?\nMs Lee: (7) ______ Just drop it in my inbox by Wednesday afternoon.","stem":"Which choice best completes gap (5)?","choices":["So you'd like me to cut it down to the key points?","So you'd like me to add more data to it?","So the directors have already approved it?","So I should send it straight to the directors?"],"answer":0,"explanation":{"en":"Ms Lee complains the summary is too long and then says 'Exactly. Lead with the two or three findings...', so Nattapong must be checking that she wants it shortened: 'So you'd like me to cut it down to the key points?'","th":"คุณลีบอกว่าบทสรุปยาวเกินไป แล้วตอบรับว่า 'Exactly' ก่อนแนะนำให้นำเสนอเฉพาะประเด็นสำคัญ ดังนั้นณัฐพงศ์ต้องถามยืนยันว่า 'So you'd like me to cut it down to the key points?'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"h","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Workplace conversation","th":"บทสนทนาในที่ทำงาน"},"passage":"Read the conversation between a manager and an intern at a marketing company.\n\nMs Lee: Nattapong, have you got a minute? It's about the market report.\nNattapong: Sure. Is something wrong with it?\nMs Lee: Not wrong exactly. The data's solid, but the summary runs to three pages. The directors won't read past the first paragraph.\nNattapong: (5) ______\nMs Lee: Exactly. Lead with the two or three findings that really matter, and put the detail in an appendix.\nNattapong: Got it. When do you need the revised version?\nMs Lee: Thursday would be ideal, but (6) ______ if you need to check the figures again.\nNattapong: Thursday should be fine. Would you mind looking over the new summary before I send it out?\nMs Lee: (7) ______ Just drop it in my inbox by Wednesday afternoon.","stem":"Which choice best completes gap (6)?","choices":["it absolutely must be done by Wednesday","the figures don't need checking","it was due last week anyway","I can live with Friday"],"answer":3,"explanation":{"en":"'But' introduces a concession to 'Thursday would be ideal', and the condition 'if you need to check the figures again' suggests extra time, so 'I can live with Friday' (I can accept Friday) is right. Wednesday is earlier, not a concession, and the other two contradict the condition.","th":"คำว่า 'but' ตามหลัง 'Thursday would be ideal' แสดงการผ่อนปรน และเงื่อนไข 'if you need to check the figures again' หมายถึงการให้เวลาเพิ่ม จึงตอบ 'I can live with Friday' (รับได้ถ้าเป็นวันศุกร์) วันพุธเร็วกว่าเดิมจึงไม่ใช่การผ่อนปรน ส่วนอีกสองคำตอบขัดกับเงื่อนไข"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Choosing language suited to register and politeness","th":"การเลือกภาษาให้เหมาะกับระดับภาษาและความสุภาพ"},"topic":{"en":"Workplace conversation","th":"บทสนทนาในที่ทำงาน"},"passage":"Read the conversation between a manager and an intern at a marketing company.\n\nMs Lee: Nattapong, have you got a minute? It's about the market report.\nNattapong: Sure. Is something wrong with it?\nMs Lee: Not wrong exactly. The data's solid, but the summary runs to three pages. The directors won't read past the first paragraph.\nNattapong: (5) ______\nMs Lee: Exactly. Lead with the two or three findings that really matter, and put the detail in an appendix.\nNattapong: Got it. When do you need the revised version?\nMs Lee: Thursday would be ideal, but (6) ______ if you need to check the figures again.\nNattapong: Thursday should be fine. Would you mind looking over the new summary before I send it out?\nMs Lee: (7) ______ Just drop it in my inbox by Wednesday afternoon.","stem":"Which choice best completes gap (7)?","choices":["Never mind about that.","Yes, I do mind, actually.","You're welcome to.","Not at all — happy to."],"answer":3,"explanation":{"en":"'Would you mind...?' is answered with 'Not at all' when you agree, and Ms Lee then tells him when to send it, so 'Not at all — happy to.' fits. 'Yes, I do mind' is a refusal, 'You're welcome to' gives permission rather than agreeing to help, and 'Never mind' dismisses the request.","th":"คำถาม 'Would you mind...?' ถ้ายินดีช่วยต้องตอบ 'Not at all' และคุณลีก็บอกต่อว่าให้ส่งมาเมื่อไร จึงตอบ 'Not at all — happy to.' ส่วน 'Yes, I do mind' คือปฏิเสธ 'You're welcome to' เป็นการอนุญาตไม่ใช่รับปากช่วย และ 'Never mind' เป็นการปัดคำขอ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Workplace conversation","th":"บทสนทนาในที่ทำงาน"},"passage":"Read the conversation between a manager and an intern at a marketing company.\n\nMs Lee: Nattapong, have you got a minute? It's about the market report.\nNattapong: Sure. Is something wrong with it?\nMs Lee: Not wrong exactly. The data's solid, but the summary runs to three pages. The directors won't read past the first paragraph.\nNattapong: (5) ______\nMs Lee: Exactly. Lead with the two or three findings that really matter, and put the detail in an appendix.\nNattapong: Got it. When do you need the revised version?\nMs Lee: Thursday would be ideal, but (6) ______ if you need to check the figures again.\nNattapong: Thursday should be fine. Would you mind looking over the new summary before I send it out?\nMs Lee: (7) ______ Just drop it in my inbox by Wednesday afternoon.","stem":"What is Ms Lee's main concern about the report?","choices":["Its summary is too long for the people who will read it.","Its data are not reliable enough.","It contains too few findings.","It was handed in after the deadline."],"answer":0,"explanation":{"en":"Ms Lee says the data is 'solid' but the summary 'runs to three pages' and the directors 'won't read past the first paragraph', so her concern is that its summary is too long for the people who will read it.","th":"คุณลีบอกว่าข้อมูล 'solid' (น่าเชื่อถือ) แต่บทสรุปยาวถึงสามหน้า และผู้บริหารจะไม่อ่านเกินย่อหน้าแรก ปัญหาคือบทสรุปยาวเกินไปสำหรับผู้อ่าน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"e","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Service conversation","th":"บทสนทนาการรับบริการ"},"passage":"Read the telephone conversation between a customer and a mobile phone company.\n\nAgent: Good afternoon, ThaiConnect customer care, this is Ploy speaking. How may I help you?\nCustomer: Hi. I've just got my bill, and I've been charged for twelve gigabytes of extra data. I'm on the unlimited plan.\nAgent: I'm sorry to hear that. (9) ______\nCustomer: Sure, it's 089-555-0142.\nAgent: Thank you... Yes, I can see the problem. Your plan was switched to the basic package on the 3rd, when the promotion period ended.\nCustomer: Nobody told me it was a promotion! (10) ______\nAgent: I completely understand your frustration. Since we didn't send you a reminder, I can refund the extra charges and move you back to unlimited at the standard rate.\nCustomer: And what's the standard rate?\nAgent: Five hundred and ninety-nine baht a month — a hundred more than the promotional price.\nCustomer: Hmm. (11) ______ Can I think about it and call you back?\nAgent: Of course. The refund will go through either way.","stem":"Which choice best completes gap (9)?","choices":["Have you tried switching your phone off and on again?","Could I have the mobile number on the account, please?","Why did you use so much data?","Would you like to upgrade to a newer phone?"],"answer":1,"explanation":{"en":"The customer replies by giving a phone number, so the agent must have asked 'Could I have the mobile number on the account, please?' 'Why did you use so much data?' is also rude to a customer.","th":"ลูกค้าตอบด้วยหมายเลขโทรศัพท์ พนักงานจึงต้องถามว่า 'Could I have the mobile number on the account, please?' ส่วน 'Why did you use so much data?' ยังเป็นคำถามที่ไม่สุภาพกับลูกค้าด้วย"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Understanding implied meaning","th":"การเข้าใจความหมายแฝง"},"topic":{"en":"Service conversation","th":"บทสนทนาการรับบริการ"},"passage":"Read the telephone conversation between a customer and a mobile phone company.\n\nAgent: Good afternoon, ThaiConnect customer care, this is Ploy speaking. How may I help you?\nCustomer: Hi. I've just got my bill, and I've been charged for twelve gigabytes of extra data. I'm on the unlimited plan.\nAgent: I'm sorry to hear that. (9) ______\nCustomer: Sure, it's 089-555-0142.\nAgent: Thank you... Yes, I can see the problem. Your plan was switched to the basic package on the 3rd, when the promotion period ended.\nCustomer: Nobody told me it was a promotion! (10) ______\nAgent: I completely understand your frustration. Since we didn't send you a reminder, I can refund the extra charges and move you back to unlimited at the standard rate.\nCustomer: And what's the standard rate?\nAgent: Five hundred and ninety-nine baht a month — a hundred more than the promotional price.\nCustomer: Hmm. (11) ______ Can I think about it and call you back?\nAgent: Of course. The refund will go through either way.","stem":"Which choice best completes gap (10)?","choices":["I'm glad the promotion has finally ended.","That explains why my bill is so low.","I'd never have used that much data if I'd known.","I knew it would end on the 3rd."],"answer":2,"explanation":{"en":"The customer is complaining that nobody warned them, so 'I'd never have used that much data if I'd known.' continues the complaint. Knowing the end date contradicts 'Nobody told me', and the bill is high, not low.","th":"ลูกค้ากำลังตำหนิว่าไม่มีใครแจ้ง จึงพูดต่อว่า 'I'd never have used that much data if I'd known.' (ถ้ารู้คงไม่ใช้เน็ตมากขนาดนั้น) การบอกว่ารู้วันสิ้นสุดขัดกับ 'Nobody told me' และค่าบริการสูง ไม่ใช่ต่ำ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"m","skill":{"en":"Understanding implied meaning","th":"การเข้าใจความหมายแฝง"},"topic":{"en":"Service conversation","th":"บทสนทนาการรับบริการ"},"passage":"Read the telephone conversation between a customer and a mobile phone company.\n\nAgent: Good afternoon, ThaiConnect customer care, this is Ploy speaking. How may I help you?\nCustomer: Hi. I've just got my bill, and I've been charged for twelve gigabytes of extra data. I'm on the unlimited plan.\nAgent: I'm sorry to hear that. (9) ______\nCustomer: Sure, it's 089-555-0142.\nAgent: Thank you... Yes, I can see the problem. Your plan was switched to the basic package on the 3rd, when the promotion period ended.\nCustomer: Nobody told me it was a promotion! (10) ______\nAgent: I completely understand your frustration. Since we didn't send you a reminder, I can refund the extra charges and move you back to unlimited at the standard rate.\nCustomer: And what's the standard rate?\nAgent: Five hundred and ninety-nine baht a month — a hundred more than the promotional price.\nCustomer: Hmm. (11) ______ Can I think about it and call you back?\nAgent: Of course. The refund will go through either way.","stem":"Which choice best completes gap (11)?","choices":["That's a real bargain.","I'll take it right away.","That's more than I was expecting.","That's exactly what I pay now."],"answer":2,"explanation":{"en":"The customer hesitates ('Hmm') and wants time to think, so the price seems high: 'That's more than I was expecting.' Calling it a bargain or accepting immediately contradicts the hesitation, and the rate is 100 baht more than before.","th":"ลูกค้าลังเล ('Hmm') และขอเวลาคิด แสดงว่าราคาสูงเกินคาด จึงตอบ 'That's more than I was expecting.' การบอกว่าคุ้มมากหรือตกลงทันทีขัดกับความลังเล และราคาใหม่แพงกว่าเดิม 100 บาท"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-short","difficulty":"h","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"Service conversation","th":"บทสนทนาการรับบริการ"},"passage":"Read the telephone conversation between a customer and a mobile phone company.\n\nAgent: Good afternoon, ThaiConnect customer care, this is Ploy speaking. How may I help you?\nCustomer: Hi. I've just got my bill, and I've been charged for twelve gigabytes of extra data. I'm on the unlimited plan.\nAgent: I'm sorry to hear that. (9) ______\nCustomer: Sure, it's 089-555-0142.\nAgent: Thank you... Yes, I can see the problem. Your plan was switched to the basic package on the 3rd, when the promotion period ended.\nCustomer: Nobody told me it was a promotion! (10) ______\nAgent: I completely understand your frustration. Since we didn't send you a reminder, I can refund the extra charges and move you back to unlimited at the standard rate.\nCustomer: And what's the standard rate?\nAgent: Five hundred and ninety-nine baht a month — a hundred more than the promotional price.\nCustomer: Hmm. (11) ______ Can I think about it and call you back?\nAgent: Of course. The refund will go through either way.","stem":"Which statement is true according to the conversation?","choices":["The plan was changed because the customer used too much data.","The customer will get the refund even without staying on the unlimited plan.","The customer was warned before the promotion ended.","The standard unlimited rate is 499 baht a month."],"answer":1,"explanation":{"en":"The agent says 'The refund will go through either way', so the customer will get the refund even without staying on the unlimited plan. No reminder was sent, the plan changed because the promotion ended, and the standard rate is 599 baht.","th":"พนักงานบอกว่า 'The refund will go through either way' คือได้เงินคืนไม่ว่าจะเลือกแพ็กเกจใด ลูกค้าไม่ได้รับการแจ้งเตือน แพ็กเกจเปลี่ยนเพราะโปรโมชันหมด และราคามาตรฐานคือ 599 บาท"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"e","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"Which choice best completes gap (13)?","choices":["You should have told me about this last year.","Electives don't really count for much.","That's a strange reason to change programmes.","That's not unusual at all."],"answer":3,"explanation":{"en":"Dr Carter continues 'Lots of students discover their real interests through electives', which supports 'That's not unusual at all.' The other replies criticise Mai, which does not match the encouraging follow-up.","th":"ดร.คาร์เตอร์พูดต่อว่า 'Lots of students discover their real interests through electives' ซึ่งสนับสนุน 'That's not unusual at all.' (เป็นเรื่องปกติ) คำตอบอื่นเป็นการตำหนิซึ่งไม่เข้ากับน้ำเสียงให้กำลังใจที่ตามมา"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"m","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"Which choice best completes gap (14)?","choices":["That means you wouldn't lose any time at all.","You'd have to start again from the first year.","Realistically, you'd be looking at an extra year.","So you could actually graduate a year early."],"answer":2,"explanation":{"en":"Mai reacts with 'An extra year?', echoing what Dr Carter has just said, so the gap must be 'Realistically, you'd be looking at an extra year.' Losing half the credits does not mean graduating early or losing no time, and starting from the first year would cost more than one year.","th":"ใหม่ทวนคำว่า 'An extra year?' แสดงว่าดร.คาร์เตอร์เพิ่งพูดถึงการเรียนเพิ่มหนึ่งปี: 'Realistically, you'd be looking at an extra year.' การเสียหน่วยกิตครึ่งหนึ่งไม่ทำให้จบเร็วขึ้นหรือไม่เสียเวลา และการเริ่มปีหนึ่งใหม่จะเสียเวลามากกว่าหนึ่งปี"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"m","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"Which choice best completes gap (15)?","choices":["So I'd have to leave engineering after all?","But I've already taken all five of them.","Five courses on top of my current load?","Only five? That's nothing."],"answer":2,"explanation":{"en":"Mai then asks whether it would fit her timetable, showing concern about the workload: 'Five courses on top of my current load?' 'That's nothing' contradicts her worry, the minor means staying in engineering, and she cannot have taken courses in a minor she has not joined.","th":"ใหม่ถามต่อว่าจะจัดตารางได้หรือไม่ แสดงความกังวลเรื่องภาระงาน จึงตอบ 'Five courses on top of my current load?' ส่วน 'That's nothing' ขัดกับความกังวล วิชาโทหมายถึงยังเรียนวิศวะอยู่ และเธอยังไม่เคยลงวิชาเหล่านั้น"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"e","skill":{"en":"Choosing an appropriate response in a conversation","th":"การเลือกถ้อยคำตอบโต้ที่เหมาะสมในบทสนทนา"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"Which choice best completes gap (16)?","choices":["I'd rather not waste my time on that.","That's a great idea — I'll do that.","I've never heard of Professor Wongsa.","I've already decided to transfer anyway."],"answer":1,"explanation":{"en":"Mai thanks Dr Carter warmly straight afterwards, so she accepts the suggestion: 'That's a great idea — I'll do that.' Refusing or saying she will transfer does not match her thanks and her relief at finding a middle way.","th":"ใหม่ขอบคุณอย่างจริงใจทันทีหลังจากนั้น แสดงว่ารับคำแนะนำ: 'That's a great idea — I'll do that.' การปฏิเสธหรือบอกว่าจะย้ายคณะแน่นอนไม่สอดคล้องกับคำขอบคุณและความโล่งใจที่พบทางสายกลาง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"m","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"Why is Mai interested in environmental studies?","choices":["Her parents have encouraged her to change.","She has always enjoyed chemistry.","She is not doing well in her structures classes.","She wants her studies to consider the wider effects of engineering projects."],"answer":3,"explanation":{"en":"Mai says environmental studies 'connects the technical work to real consequences' and that nobody asks 'whether the bridge should be built at all', so she wants her studies to consider the wider effects of engineering projects. She never mentions poor grades, and she has not studied chemistry since school.","th":"ใหม่บอกว่าวิชาสิ่งแวดล้อม 'connects the technical work to real consequences' และไม่มีใครถามว่าควรสร้างสะพานหรือไม่ เธอจึงอยากเรียนสิ่งที่คำนึงถึงผลกระทบในวงกว้างของงานวิศวกรรม ไม่ได้พูดถึงผลการเรียนไม่ดี และไม่ได้เรียนเคมีมาตั้งแต่มัธยม"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"h","skill":{"en":"Understanding implied meaning","th":"การเข้าใจความหมายแฝง"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"When Dr Carter says 'I'd say good engineers do ask that question', she is","choices":["suggesting that Mai will never be a good engineer","politely questioning Mai's view of engineering","trying to change the subject to chemistry","agreeing that engineers ignore the consequences of their work"],"answer":1,"explanation":{"en":"She first grants 'That's a fair point, although...' and then states that good engineers do consider whether a project should be built — a polite way of questioning Mai's view of engineering. She is not agreeing with Mai and is not attacking her.","th":"เธอพูดว่า 'That's a fair point, although...' แล้วจึงบอกว่าวิศวกรที่ดีก็ถามคำถามนั้น เป็นการโต้แย้งมุมมองของใหม่อย่างสุภาพ (politely questioning Mai's view of engineering) ไม่ใช่การเห็นด้วยหรือการดูถูกใหม่"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"m","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"In the conversation, the phrase 'double as' is closest in meaning to","choices":["completely replace","are taught twice a week as","also count as","are twice as difficult as"],"answer":2,"explanation":{"en":"Several minor courses 'double as engineering electives', so they also count as electives — that is why there are 'only two or three extra' courses.","th":"วิชาในวิชาโทหลายวิชา 'double as engineering electives' คือนับเป็นวิชาเลือกของวิศวะได้ด้วย (also count as) จึงต้องเรียนเพิ่มจริงเพียงสองสามวิชา"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"conversation-long","difficulty":"h","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"Campus conversation","th":"บทสนทนาในมหาวิทยาลัย"},"passage":"Read the conversation between Mai, a second-year student, and her academic advisor, Dr Carter.\n\nDr Carter: Come in, Mai. Your email said you're thinking about changing programmes?\nMai: Yes. I'm in my second year of civil engineering, but honestly, the course I enjoyed most last term was the environmental impact one — and that was only an elective.\nDr Carter: (13) ______ Lots of students discover their real interests through electives. What is it about the environmental side that appeals to you?\nMai: I like that it connects the technical work to real consequences. In my structures classes we calculate loads all day, but nobody asks whether the bridge should be built at all.\nDr Carter: That's a fair point, although I'd say good engineers do ask that question. Have you looked at the Environmental Science requirements?\nMai: A little. I'd need chemistry, which I haven't studied since high school.\nDr Carter: Right. And here's the thing — if you transfer, only about half of your engineering credits would count. (14) ______\nMai: An extra year? My parents won't be thrilled about that.\nDr Carter: There may be a middle way. We introduced a minor in Environmental Systems last year. You'd stay in civil engineering but take five related courses on top.\nMai: (15) ______ Would that even fit in my timetable?\nDr Carter: It's a heavy load, I won't pretend otherwise. But several of the minor's courses double as engineering electives, so in practice it's only two or three extra.\nMai: That sounds much more manageable. Who should I talk to about signing up?\nDr Carter: Professor Wongsa coordinates it. I'd also suggest you sit in on her water-quality class next week before you commit.\nMai: (16) ______ Thank you so much. I came in thinking I had to choose one or the other.\nDr Carter: Not at all. Just don't let the decision drift — applications for the minor close at the end of the month.","stem":"What is the main advantage of the minor over transferring, according to the conversation?","choices":["Mai would not need anyone's approval to join it.","Mai can follow her new interest without adding a year to her studies.","It does not require any extra courses.","It allows Mai to stop studying civil engineering."],"answer":1,"explanation":{"en":"Transferring would cost about an extra year, while the minor lets her stay in civil engineering with only two or three extra courses, so she can follow her new interest without adding a year to her studies. It does require extra courses, and she would remain an engineering student.","th":"การย้ายคณะต้องเรียนเพิ่มราวหนึ่งปี แต่วิชาโททำให้เรียนวิศวะต่อและลงเพิ่มเพียงสองสามวิชา จึงได้เรียนสิ่งที่สนใจโดยไม่ต้องเรียนเพิ่มอีกปี วิชาโทยังต้องลงวิชาเพิ่ม และเธอยังเป็นนักศึกษาวิศวะอยู่"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"m","skill":{"en":"Applying information to a situation","th":"การนำข้อมูลไปใช้กับสถานการณ์"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"STUDYHIVE — Quiet Study & Co-working Space\nJust 3 minutes' walk from the university's North Gate\n\nOpen: 7 a.m. – midnight (Mon–Sat) | 9 a.m. – 9 p.m. (Sun)\n• Silent Zone: phones on mute, no calls\n• Group rooms for 4–8 people (book online, max. 3 hours) — monthly members only\n• High-speed Wi-Fi • Printing 2 baht/page • Free drinking water, coffee bar in the lobby\n\nPRICES\nDay pass ............................ 120 baht\n10-visit card (valid 60 days) ........ 990 baht\nMonthly unlimited ................. 1,800 baht\nStudents with a valid ID: 20% off monthly memberships only\n\nEXAM SEASON SPECIAL (1–31 May): Buy a monthly membership and get one group-room session FREE!","stem":"A student with a valid ID buys a monthly membership on 10 May. What will the student pay, and what extra will the student receive?","choices":["1,620 baht and unlimited group-room use","1,440 baht and one free group-room session","1,440 baht and free printing for the month","1,800 baht and one free group-room session"],"answer":1,"explanation":{"en":"Students get 20% off monthly memberships: 1,800 − 360 = 1,440 baht, and the May special adds one free group-room session. So the answer is 1,440 baht and one free group-room session.","th":"นักศึกษาได้ส่วนลด 20% สำหรับสมาชิกรายเดือน: 1,800 − 360 = 1,440 บาท และโปรโมชันเดือนพฤษภาคมแถมห้องกลุ่มฟรีหนึ่งครั้ง คำตอบจึงเป็น 1,440 บาทพร้อมห้องกลุ่มฟรีหนึ่งครั้ง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"m","skill":{"en":"Applying information to a situation","th":"การนำข้อมูลไปใช้กับสถานการณ์"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"STUDYHIVE — Quiet Study & Co-working Space\nJust 3 minutes' walk from the university's North Gate\n\nOpen: 7 a.m. – midnight (Mon–Sat) | 9 a.m. – 9 p.m. (Sun)\n• Silent Zone: phones on mute, no calls\n• Group rooms for 4–8 people (book online, max. 3 hours) — monthly members only\n• High-speed Wi-Fi • Printing 2 baht/page • Free drinking water, coffee bar in the lobby\n\nPRICES\nDay pass ............................ 120 baht\n10-visit card (valid 60 days) ........ 990 baht\nMonthly unlimited ................. 1,800 baht\nStudents with a valid ID: 20% off monthly memberships only\n\nEXAM SEASON SPECIAL (1–31 May): Buy a monthly membership and get one group-room session FREE!","stem":"Which customer could NOT book a group room?","choices":["A student who paid the discounted monthly price","A monthly member who wants a room for three hours","Someone using a 10-visit card","A monthly member booking for a group of six"],"answer":2,"explanation":{"en":"Group rooms are for 'monthly members only', so someone using a 10-visit card cannot book one. Three hours and six people are within the limits, and a discounted monthly member is still a monthly member.","th":"ห้องกลุ่มใช้ได้เฉพาะ 'monthly members only' ผู้ที่ใช้บัตร 10 ครั้งจึงจองไม่ได้ ส่วนการจองสามชั่วโมงและกลุ่มหกคนอยู่ในเงื่อนไข และนักศึกษาที่จ่ายราคาลดก็ยังเป็นสมาชิกรายเดือน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"h","skill":{"en":"Comparing and calculating from data","th":"การเปรียบเทียบและคำนวณจากข้อมูล"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"STUDYHIVE — Quiet Study & Co-working Space\nJust 3 minutes' walk from the university's North Gate\n\nOpen: 7 a.m. – midnight (Mon–Sat) | 9 a.m. – 9 p.m. (Sun)\n• Silent Zone: phones on mute, no calls\n• Group rooms for 4–8 people (book online, max. 3 hours) — monthly members only\n• High-speed Wi-Fi • Printing 2 baht/page • Free drinking water, coffee bar in the lobby\n\nPRICES\nDay pass ............................ 120 baht\n10-visit card (valid 60 days) ........ 990 baht\nMonthly unlimited ................. 1,800 baht\nStudents with a valid ID: 20% off monthly memberships only\n\nEXAM SEASON SPECIAL (1–31 May): Buy a monthly membership and get one group-room session FREE!","stem":"Compared with buying ten separate day passes, how much does the 10-visit card save?","choices":["210 baht","810 baht","120 baht","240 baht"],"answer":0,"explanation":{"en":"Ten day passes cost 10 × 120 = 1,200 baht; the card costs 990 baht, so it saves 210 baht. The student discount does not apply to either.","th":"บัตรรายวันสิบใบราคา 10 × 120 = 1,200 บาท บัตร 10 ครั้งราคา 990 บาท จึงประหยัด 210 บาท และส่วนลดนักศึกษาใช้กับบัตรทั้งสองแบบนี้ไม่ได้"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"m","skill":{"en":"Applying information to a situation","th":"การนำข้อมูลไปใช้กับสถานการณ์"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"PART-TIME RESEARCH ASSISTANT WANTED\nFaculty of Public Health — Urban Air Quality Project\n\nWe are looking for a reliable, detail-oriented student to help with field data collection and data entry.\n\nDuties: setting up and checking air sensors at 12 sites across Bangkok (some early mornings); entering and cleaning data in Excel; helping to prepare monthly summaries.\n\nRequirements: current undergraduate (Year 2 or above), any faculty; basic Excel skills; able to travel independently around the city. Knowledge of R or Python is an advantage but not essential.\n\nHours: 10–12 hours per week, flexible, for six months (June–November)\nPay: 150 baht/hour plus travel expenses\n\nTo apply: send a CV and a short statement (max. 300 words) explaining your interest to the project office by 15 May. Shortlisted applicants will be asked to complete a 20-minute Excel task.","stem":"Which applicant meets ALL the stated requirements?","choices":["A third-year engineering student who knows Python but has never used Excel","A recent graduate with excellent R and Excel skills","A second-year economics student who uses Excel and can get around Bangkok alone","A first-year public health student who is fluent in Python"],"answer":2,"explanation":{"en":"The job needs a current undergraduate in Year 2 or above from any faculty, with basic Excel and able to travel independently: the second-year economics student who uses Excel and can get around Bangkok alone. A first-year student, a graduate and someone without Excel each fail one requirement.","th":"งานนี้ต้องการนักศึกษาปริญญาตรีปี 2 ขึ้นไปจากคณะใดก็ได้ ใช้ Excel ได้ และเดินทางเองได้ จึงเป็นนักศึกษาเศรษฐศาสตร์ปี 2 ที่ใช้ Excel และเดินทางในกรุงเทพฯ เองได้ ส่วนนักศึกษาปี 1 ผู้ที่จบแล้ว และคนที่ไม่เคยใช้ Excel ขาดคุณสมบัติคนละอย่าง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"e","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"PART-TIME RESEARCH ASSISTANT WANTED\nFaculty of Public Health — Urban Air Quality Project\n\nWe are looking for a reliable, detail-oriented student to help with field data collection and data entry.\n\nDuties: setting up and checking air sensors at 12 sites across Bangkok (some early mornings); entering and cleaning data in Excel; helping to prepare monthly summaries.\n\nRequirements: current undergraduate (Year 2 or above), any faculty; basic Excel skills; able to travel independently around the city. Knowledge of R or Python is an advantage but not essential.\n\nHours: 10–12 hours per week, flexible, for six months (June–November)\nPay: 150 baht/hour plus travel expenses\n\nTo apply: send a CV and a short statement (max. 300 words) explaining your interest to the project office by 15 May. Shortlisted applicants will be asked to complete a 20-minute Excel task.","stem":"The phrase 'an advantage but not essential' suggests that programming skills","choices":["may help an applicant but are not required","will be taught during the project","are required for all applicants","are less useful than travel experience"],"answer":0,"explanation":{"en":"'Essential' means necessary; 'an advantage but not essential' means such skills may help an applicant but are not required.","th":"'Essential' แปลว่าจำเป็น 'an advantage but not essential' จึงหมายถึงทักษะนั้นช่วยให้ได้เปรียบแต่ไม่บังคับ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-ads","difficulty":"e","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"Advertisement","th":"โฆษณา"},"passage":"PART-TIME RESEARCH ASSISTANT WANTED\nFaculty of Public Health — Urban Air Quality Project\n\nWe are looking for a reliable, detail-oriented student to help with field data collection and data entry.\n\nDuties: setting up and checking air sensors at 12 sites across Bangkok (some early mornings); entering and cleaning data in Excel; helping to prepare monthly summaries.\n\nRequirements: current undergraduate (Year 2 or above), any faculty; basic Excel skills; able to travel independently around the city. Knowledge of R or Python is an advantage but not essential.\n\nHours: 10–12 hours per week, flexible, for six months (June–November)\nPay: 150 baht/hour plus travel expenses\n\nTo apply: send a CV and a short statement (max. 300 words) explaining your interest to the project office by 15 May. Shortlisted applicants will be asked to complete a 20-minute Excel task.","stem":"What will happen to shortlisted applicants?","choices":["They will write a 300-word statement.","They will complete a short practical task using Excel.","They will start collecting data immediately.","They will be interviewed by the faculty dean."],"answer":1,"explanation":{"en":"The ad says shortlisted applicants 'will be asked to complete a 20-minute Excel task', i.e. a short practical task using Excel. The 300-word statement is part of the first application, not the shortlist stage.","th":"ประกาศระบุว่าผู้ผ่านการคัดเลือกเบื้องต้นจะต้อง 'complete a 20-minute Excel task' คือทำแบบทดสอบ Excel สั้น ๆ ส่วนเรียงความ 300 คำเป็นส่วนของการสมัครขั้นแรก"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"e","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"What does the reviewer say about the battery?","choices":["It stopped working after a software update.","It runs out quickly when the warm light is on.","It needs charging every night.","It lasts about three weeks between charges."],"answer":3,"explanation":{"en":"She writes 'I charge it about once every three weeks', so it lasts about three weeks between charges. The software problem was a frozen screen, not the battery.","th":"ผู้วิจารณ์เขียนว่า 'I charge it about once every three weeks' แบตเตอรี่จึงใช้ได้ราวสามสัปดาห์ต่อการชาร์จหนึ่งครั้ง ปัญหาหลังอัปเดตซอฟต์แวร์คือหน้าจอค้าง ไม่ใช่แบตเตอรี่"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"m","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"In the review, a 'deal-breaker' is","choices":["a special offer that ends soon","a problem serious enough to stop someone buying the product","a fault that the company repairs for free","a feature that makes a product cheaper"],"answer":1,"explanation":{"en":"She says slower page turns are 'not a deal-breaker, but noticeable', meaning the problem is not serious enough to stop someone buying the product.","th":"เธอบอกว่าการเปลี่ยนหน้าช้า 'not a deal-breaker, but noticeable' หมายถึงเป็นข้อเสียที่ไม่ร้ายแรงถึงขั้นทำให้ไม่ซื้อ ดังนั้น deal-breaker คือปัญหาที่ร้ายแรงพอจะทำให้ไม่ซื้อสินค้า"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"m","skill":{"en":"Identifying the writer's purpose","th":"การระบุจุดประสงค์ของผู้เขียน"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"Why does the reviewer mention dropping the e-reader in the bath?","choices":["To warn readers not to use it near water","To complain that the case did not protect it","To confirm from her own experience that it is waterproof","To explain why she needed customer service"],"answer":2,"explanation":{"en":"Right after saying 'It's also waterproof, which I tested — unintentionally', she reports that it 'survived without a scratch', so the story confirms from her own experience that it is waterproof. Customer service was needed for the frozen screen.","th":"หลังจากบอกว่า 'It's also waterproof, which I tested — unintentionally' เธอเล่าว่าเครื่อง 'survived without a scratch' จึงเป็นการยืนยันจากประสบการณ์จริงว่ากันน้ำได้ ส่วนการติดต่อฝ่ายบริการเกิดจากหน้าจอค้าง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"m","skill":{"en":"Identifying information that is not stated","th":"การระบุข้อมูลที่ไม่ได้กล่าวถึง"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"Which problem is NOT mentioned in the review?","choices":["Turning pages is a little slow.","The case is expensive for its quality.","Many books are not available in the Lumo store.","The screen is hard to read in bright sunlight."],"answer":3,"explanation":{"en":"The review mentions the small store, slow page turns and the overpriced case, but says nothing about reading in sunlight; it actually praises the screen. So 'The screen is hard to read in bright sunlight' is not mentioned.","th":"บทวิจารณ์พูดถึงร้านหนังสือที่มีหนังสือน้อย การเปลี่ยนหน้าช้า และเคสที่แพงเกินคุณภาพ แต่ไม่ได้พูดถึงการอ่านกลางแดด ซึ่งกลับชมหน้าจอด้วย คำตอบจึงเป็น 'The screen is hard to read in bright sunlight.'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"h","skill":{"en":"Identifying attitude and tone","th":"การระบุทัศนคติและน้ำเสียง"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"What is the reviewer's attitude towards customer service?","choices":["Annoyed that the update caused a problem","Disappointed that support was closed on Sunday","Unsure whether the fix will last","Impressed by how quickly the problem was solved"],"answer":3,"explanation":{"en":"She says customer service 'deserves a mention' and got a fix 'within two hours' on a Sunday, so she is impressed by how quickly the problem was solved.","th":"เธอบอกว่าฝ่ายบริการ 'deserves a mention' และได้รับการแก้ไขภายในสองชั่วโมงแม้เป็นวันอาทิตย์ แสดงว่าประทับใจความรวดเร็วในการแก้ปัญหา"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-review","difficulty":"h","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"Product / service review","th":"บทวิจารณ์สินค้าและบริการ"},"passage":"Lumo Page 7 e-reader — reviewed by Kanya R. ★★★★☆\n\nI've owned the Lumo Page 7 for three months, mostly reading on my commute and in bed, so here's an honest take.\n\nThe good: The 7-inch screen is the best I've used at this price. Text is sharp, and the warm-light setting means I can read late at night without the glare that used to keep me awake when I read on my tablet. Battery life is genuinely impressive: I charge it about once every three weeks. It's also waterproof, which I tested — unintentionally — when I dropped it in the bath. It survived without a scratch.\n\nThe not-so-good: The Lumo store is still small. About a third of the titles on my wish list weren't available, so I've ended up buying some e-books elsewhere and transferring them by cable, which is fiddly. Page turns are slightly slower than on my old e-reader — not a deal-breaker, but noticeable if you read fast. And the case, sold separately at 890 baht, feels overpriced for what is basically folded plastic.\n\nCustomer service deserves a mention. When the screen froze after a software update, I contacted support on a Sunday and had a fix within two hours.\n\nVerdict: At 4,290 baht, the Page 7 is excellent value if you mostly read novels and don't mind shopping around for books. If you rely on a large store and instant downloads, you may be happier paying more for a better-known brand.","stem":"According to the verdict, who would be most likely to enjoy the Page 7?","choices":["A novel reader who is happy to buy books from different sources","A reader who wants every book available instantly in one store","A buyer who wants the best-known brand at any price","A student who needs to read large colour diagrams"],"answer":0,"explanation":{"en":"The verdict says it is 'excellent value if you mostly read novels and don't mind shopping around for books' — a novel reader who is happy to buy books from different sources. People who need a large store are advised to choose another brand.","th":"บทสรุปบอกว่า 'excellent value if you mostly read novels and don't mind shopping around for books' คือเหมาะกับคนที่อ่านนวนิยายและยอมซื้อหนังสือจากหลายแหล่ง ส่วนคนที่ต้องการร้านใหญ่และดาวน์โหลดทันทีควรเลือกยี่ห้ออื่น"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"e","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"What is the news report mainly about?","choices":["A plan to ban agricultural burning around Chiang Mai","Falling tourist numbers in Chiang Mai's old town","A university study proving that traffic causes haze","A short trial of traffic restrictions aimed at reducing air pollution"],"answer":3,"explanation":{"en":"The report describes an eight-week scheme closing the old town to private cars to reduce pollution, with reactions to it — a short trial of traffic restrictions aimed at reducing air pollution. Burning and tourism are mentioned only as part of the discussion, and the study has not proved anything yet.","th":"ข่าวรายงานโครงการแปดสัปดาห์ที่ห้ามรถส่วนตัวเข้าเมืองเก่าเพื่อลดมลพิษ พร้อมความเห็นต่าง ๆ จึงเป็นการทดลองจำกัดการจราจรเพื่อลดมลพิษทางอากาศ ส่วนการเผาและนักท่องเที่ยวเป็นเพียงประเด็นประกอบ และงานวิจัยยังไม่ได้พิสูจน์อะไร"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"m","skill":{"en":"Applying information to a situation","th":"การนำข้อมูลไปใช้กับสถานการณ์"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"Which vehicle would NOT be allowed inside the moat at noon on a Tuesday during the trial?","choices":["A delivery van","A car belonging to an old-town resident","A city bus","An ambulance"],"answer":0,"explanation":{"en":"Delivery vans are allowed only 'before 10 a.m.', so a delivery van would be refused at noon. Buses, emergency vehicles and residents' vehicles are allowed all day.","th":"รถส่งของเข้าได้เฉพาะ 'before 10 a.m.' ตอนเที่ยงจึงเข้าไม่ได้ ส่วนรถเมล์ รถฉุกเฉิน และรถของผู้อยู่อาศัยเข้าได้ทั้งวัน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"h","skill":{"en":"Identifying attitude and tone","th":"การระบุทัศนคติและน้ำเสียง"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"Which best describes the Deputy Mayor's position?","choices":["She thinks the trial will solve the haze problem.","She admits traffic is not the main cause but believes the city must still act.","She believes traffic is the main source of PM2.5.","She blames farmers and says the city cannot do anything."],"answer":1,"explanation":{"en":"She acknowledges that most PM2.5 comes from burning and fires, 'not traffic', but says 'we cannot ask farmers to change while doing nothing ourselves', and calls the trial 'a first step rather than a solution'.","th":"รองนายกฯ ยอมรับว่า PM2.5 ส่วนใหญ่มาจากการเผา 'not traffic' แต่บอกว่า 'we cannot ask farmers to change while doing nothing ourselves' และเรียกโครงการนี้ว่า 'a first step rather than a solution' จึงยอมรับว่ารถไม่ใช่สาเหตุหลักแต่เมืองก็ต้องลงมือ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"m","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"The word 'blankets' in paragraph 3 is closest in meaning to","choices":["warms gently","covers thickly","disappears from","protects safely"],"answer":1,"explanation":{"en":"Haze 'blankets the north' means it covers the region thickly, like a blanket over a bed.","th":"หมอกควัน 'blankets the north' หมายถึงปกคลุมภาคเหนืออย่างหนาแน่นเหมือนผ้าห่ม (covers thickly)"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"h","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"What is Anan Chaiyo's main worry?","choices":["The scheme may further reduce visitors in a month that is already quiet.","Smoke from fires will damage his guesthouse.","Tourists will park at the park-and-ride sites.","Delivery vans will not be able to reach him."],"answer":0,"explanation":{"en":"He says tourists 'already stay away in March because of the smoke' and 'now they'll have another reason not to come', so he fears the scheme will further reduce visitors in a month that is already quiet.","th":"เขาบอกว่านักท่องเที่ยว 'already stay away in March because of the smoke' และ 'now they'll have another reason not to come' จึงกังวลว่าจำนวนนักท่องเที่ยวที่น้อยอยู่แล้วจะลดลงอีก"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"e","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"What does the Northern Breath Network want the city to do?","choices":["Close the old town every day","Make detailed air-quality readings available to the public","Pay business owners for lost sales","Cancel the car-free days"],"answer":1,"explanation":{"en":"The spokesperson says the city 'should publish hourly air-quality readings from every district', i.e. make detailed air-quality readings available to the public.","th":"โฆษกกลุ่มบอกว่าเมือง 'should publish hourly air-quality readings from every district' คือเปิดเผยข้อมูลคุณภาพอากาศอย่างละเอียดให้ประชาชนรู้"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"h","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"Why might the researchers' results be hard to interpret?","choices":["Residents will still be allowed to drive inside the moat.","The sensors will be placed only inside the old town.","Other factors affect pollution levels much more than traffic does.","The trial is planned to last for several seasons."],"answer":2,"explanation":{"en":"Dr Pimchanok says 'wind direction and the number of fires... have a far bigger effect than traffic', so other factors affect pollution much more than traffic and can hide the trial's effect. The sensors are both inside and outside, and the trial lasts only eight weeks.","th":"ดร.พิมพ์ชนกบอกว่า 'wind direction and the number of fires... have a far bigger effect than traffic' ปัจจัยอื่นมีผลต่อมลพิษมากกว่ารถมาก จึงอาจบดบังผลของโครงการ เซ็นเซอร์ติดทั้งในและนอกเมืองเก่า และโครงการมีเพียงแปดสัปดาห์"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-news","difficulty":"m","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"News report","th":"ข่าว"},"passage":"Chiang Mai trials car-free days as haze season begins\n\nCHIANG MAI — City authorities will close the old town to private cars on two weekdays a week from next month in an attempt to reduce air pollution during the annual haze season, officials announced on Monday.\n\nUnder the scheme, which runs for eight weeks from 1 March, only buses, emergency vehicles, residents' vehicles and delivery vans before 10 a.m. will be allowed inside the moat on Tuesdays and Thursdays. Free shuttle buses will run every ten minutes from three park-and-ride sites on the edge of the city.\n\nDeputy Mayor Siriporn Kaewmanee said the trial was \"a first step rather than a solution\". Most of the fine particulate matter known as PM2.5 that blankets the north each spring comes from agricultural burning and forest fires, not traffic, she acknowledged. \"But we cannot ask farmers to change while doing nothing ourselves. Traffic is the part of the problem the city controls.\"\n\nThe announcement received a mixed reaction. Business owners in the old town fear that fewer visitors will mean lower sales. \"Tourists already stay away in March because of the smoke,\" said Anan Chaiyo, who runs a guesthouse near Tha Phae Gate. \"Now they'll have another reason not to come.\"\n\nEnvironmental groups welcomed the move but said it did not go far enough. A spokesperson for the Northern Breath Network said the city should publish hourly air-quality readings from every district so that residents could judge for themselves whether the trial was working.\n\nResearchers at a local university will place sensors at 20 points inside and outside the old town to compare readings on car-free and normal days. Dr Pimchanok Saelee, who leads the team, warned that the results might be hard to interpret. \"Wind direction and the number of fires on a given day have a far bigger effect than traffic,\" she said. \"We'll need several seasons of data before we can say anything with confidence.\"\n\nIf the trial is judged successful, the city council will consider extending it to the whole haze season next year.","stem":"It can be inferred that whether the scheme continues next year depends mainly on","choices":["the agreement of local farmers","a decision by the national government","an assessment of how well the trial works","the number of tourists in March"],"answer":2,"explanation":{"en":"The last sentence says the council will consider extending it 'if the trial is judged successful', so its future depends on an assessment of how well the trial works.","th":"ประโยคสุดท้ายบอกว่าสภาเมืองจะพิจารณาขยายเวลา 'if the trial is judged successful' อนาคตของโครงการจึงขึ้นกับการประเมินผลการทดลอง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"e","skill":{"en":"Interpreting data in a table","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows the results of two surveys of students at a Thai university, carried out ten years apart. In each survey, every student named one main way of travelling to campus. 1,200 students took part in the 2025 survey. Journey times are 2025 averages.","stem":"Which mode showed the largest increase between 2015 and 2025?","choices":["Motorcycle","The university shuttle","Bicycle / walking","Public bus"],"answer":1,"explanation":{"en":"The university shuttle rose from 5% to 21% (+16 points), more than bicycle / walking (+13). Motorcycle and bus use fell.","th":"รถรับส่งของมหาวิทยาลัย (university shuttle) เพิ่มจาก 5% เป็น 21% (+16) มากกว่าจักรยาน/เดิน (+13) ส่วนมอเตอร์ไซค์และรถเมล์ลดลง"},"table":{"title":"Main way of travelling to campus (% of students)","rows":[["Mode","2015","2025","Average journey 2025 (min)"],["Private car","28","14","42"],["Motorcycle","35","22","25"],["Public bus","20","18","50"],["University shuttle","5","21","30"],["Bicycle / walking","12","25","15"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"m","skill":{"en":"Comparing and calculating from data","th":"การเปรียบเทียบและคำนวณจากข้อมูล"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows the results of two surveys of students at a Thai university, carried out ten years apart. In each survey, every student named one main way of travelling to campus. 1,200 students took part in the 2025 survey. Journey times are 2025 averages.","stem":"About how many students in the 2025 survey travelled mainly by university shuttle?","choices":["300","21","210","252"],"answer":3,"explanation":{"en":"21% of 1,200 = 0.21 × 1,200 = 252 students.","th":"21% ของ 1,200 คน = 0.21 × 1,200 = 252 คน"},"table":{"title":"Main way of travelling to campus (% of students)","rows":[["Mode","2015","2025","Average journey 2025 (min)"],["Private car","28","14","42"],["Motorcycle","35","22","25"],["Public bus","20","18","50"],["University shuttle","5","21","30"],["Bicycle / walking","12","25","15"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"m","skill":{"en":"Interpreting data in a table","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows the results of two surveys of students at a Thai university, carried out ten years apart. In each survey, every student named one main way of travelling to campus. 1,200 students took part in the 2025 survey. Journey times are 2025 averages.","stem":"Which statement is supported by the table?","choices":["In 2025, more students cycled or walked than used any other single mode.","Car use fell by about one third between 2015 and 2025.","The bus showed the largest fall of any mode.","Fewer than one in five students used private vehicles in 2025."],"answer":0,"explanation":{"en":"In 2025, bicycle / walking (25%) was higher than every other mode. Car use halved (28→14), the motorcycle had the largest fall (−13), and private vehicles (car + motorcycle) were 36%, well over one in five.","th":"ปี 2025 จักรยาน/เดิน (25%) สูงกว่าทุกวิธีอื่น การใช้รถยนต์ลดลงครึ่งหนึ่ง (28→14) มอเตอร์ไซค์ลดลงมากที่สุด (−13) และยานพาหนะส่วนตัวรวมกันเป็น 36% มากกว่าหนึ่งในห้า"},"table":{"title":"Main way of travelling to campus (% of students)","rows":[["Mode","2015","2025","Average journey 2025 (min)"],["Private car","28","14","42"],["Motorcycle","35","22","25"],["Public bus","20","18","50"],["University shuttle","5","21","30"],["Bicycle / walking","12","25","15"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"h","skill":{"en":"Drawing valid conclusions from data","th":"การสรุปผลที่สมเหตุสมผลจากข้อมูล"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows the results of two surveys of students at a Thai university, carried out ten years apart. In each survey, every student named one main way of travelling to campus. 1,200 students took part in the 2025 survey. Journey times are 2025 averages.","stem":"Which conclusion can most reasonably be drawn from the table?","choices":["Most students live too far away to walk to campus.","Students now choose whichever mode is fastest.","Over the decade, students moved away from private motor vehicles.","Bus journeys became much slower between 2015 and 2025."],"answer":2,"explanation":{"en":"Car plus motorcycle fell from 63% to 36%, so students moved away from private motor vehicles. The table gives journey times only for 2025, so nothing can be said about buses becoming slower, and the shuttle (30 min) grew more than faster options, so students are not simply choosing the fastest mode.","th":"รถยนต์รวมมอเตอร์ไซค์ลดจาก 63% เหลือ 36% แสดงว่านักศึกษาหันออกจากยานพาหนะส่วนตัว ตารางมีเวลาเดินทางเฉพาะปี 2025 จึงสรุปไม่ได้ว่ารถเมล์ช้าลง และรถรับส่ง (30 นาที) เพิ่มขึ้นมากกว่าทางเลือกที่เร็วกว่า จึงสรุปไม่ได้ว่าเลือกวิธีที่เร็วที่สุด"},"table":{"title":"Main way of travelling to campus (% of students)","rows":[["Mode","2015","2025","Average journey 2025 (min)"],["Private car","28","14","42"],["Motorcycle","35","22","25"],["Public bus","20","18","50"],["University shuttle","5","21","30"],["Bicycle / walking","12","25","15"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"h","skill":{"en":"Interpreting data in a table","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows results from a national survey of smartphone, computer and TV use in 2025. Respondents recorded the time they spent on each activity over one week; the figures are daily averages.","stem":"Which activity takes up the most time for people aged 19–24?","choices":["Video streaming","Social media","Work / study","Gaming"],"answer":2,"explanation":{"en":"For 19–24 year-olds, work / study is 2.9 hours, just above social media at 2.8 hours.","th":"กลุ่มอายุ 19–24 ปีใช้เวลากับ work / study 2.9 ชั่วโมง มากกว่าสื่อสังคมออนไลน์ (2.8 ชั่วโมง) เล็กน้อย"},"table":{"title":"Average daily screen time (hours) by activity and age group","rows":[["Activity","15–18","19–24","25–40","41–60"],["Social media","3.1","2.8","1.9","1.2"],["Video streaming","2.2","2.5","1.8","1.6"],["Gaming","1.5","1.1","0.6","0.2"],["Work / study","1.4","2.9","3.6","2.2"],["Total","8.2","9.3","7.9","5.2"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"m","skill":{"en":"Interpreting data in a table","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows results from a national survey of smartphone, computer and TV use in 2025. Respondents recorded the time they spent on each activity over one week; the figures are daily averages.","stem":"Which statement is supported by the table?","choices":["People aged 41–60 spend more time on work / study than those aged 25–40.","Time spent gaming falls with every older age group.","Teenagers spend more than half of their screen time on social media.","Video streaming is the main leisure activity in every age group."],"answer":1,"explanation":{"en":"Gaming falls 1.5 → 1.1 → 0.6 → 0.2. For 15–18 social media (3.1) beats streaming, 41–60 work / study (2.2) is lower than 25–40 (3.6), and 3.1 of 8.2 hours is under half.","th":"เวลาเล่นเกมลดลง 1.5 → 1.1 → 0.6 → 0.2 ตามอายุ ส่วนกลุ่ม 15–18 ใช้สื่อสังคม (3.1) มากกว่าดูวิดีโอ กลุ่ม 41–60 ทำงาน/เรียน (2.2) น้อยกว่ากลุ่ม 25–40 (3.6) และ 3.1 จาก 8.2 ชั่วโมงไม่ถึงครึ่ง"},"table":{"title":"Average daily screen time (hours) by activity and age group","rows":[["Activity","15–18","19–24","25–40","41–60"],["Social media","3.1","2.8","1.9","1.2"],["Video streaming","2.2","2.5","1.8","1.6"],["Gaming","1.5","1.1","0.6","0.2"],["Work / study","1.4","2.9","3.6","2.2"],["Total","8.2","9.3","7.9","5.2"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"h","skill":{"en":"Comparing and calculating from data","th":"การเปรียบเทียบและคำนวณจากข้อมูล"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows results from a national survey of smartphone, computer and TV use in 2025. Respondents recorded the time they spent on each activity over one week; the figures are daily averages.","stem":"For people aged 25–40, roughly what proportion of total screen time is spent on work / study?","choices":["Exactly one-third","Just under half","About a quarter","About two-thirds"],"answer":1,"explanation":{"en":"3.6 ÷ 7.9 ≈ 0.46, so just under half.","th":"3.6 ÷ 7.9 ≈ 0.46 จึงเกือบครึ่งหนึ่ง (just under half)"},"table":{"title":"Average daily screen time (hours) by activity and age group","rows":[["Activity","15–18","19–24","25–40","41–60"],["Social media","3.1","2.8","1.9","1.2"],["Video streaming","2.2","2.5","1.8","1.6"],["Gaming","1.5","1.1","0.6","0.2"],["Work / study","1.4","2.9","3.6","2.2"],["Total","8.2","9.3","7.9","5.2"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-visual","difficulty":"h","skill":{"en":"Drawing valid conclusions from data","th":"การสรุปผลที่สมเหตุสมผลจากข้อมูล"},"topic":{"en":"Table with caption","th":"ตารางพร้อมคำอธิบาย"},"passage":"The table shows results from a national survey of smartphone, computer and TV use in 2025. Respondents recorded the time they spent on each activity over one week; the figures are daily averages.","stem":"Which claim goes BEYOND what the table shows?","choices":["People aged 41–60 have the lowest total screen time.","Video streaming time is highest among 19–24 year-olds.","Heavy social media use causes teenagers to sleep less.","Social media time decreases as age increases."],"answer":2,"explanation":{"en":"The table reports hours of use only; it contains no data on sleep or on causes, so 'Heavy social media use causes teenagers to sleep less' goes beyond it. The other three statements can be read directly from the figures.","th":"ตารางแสดงเพียงจำนวนชั่วโมงที่ใช้ ไม่มีข้อมูลการนอนหรือสาเหตุ ข้อความ 'Heavy social media use causes teenagers to sleep less' จึงเกินกว่าข้อมูล ส่วนข้อความอื่นอ่านได้จากตัวเลขโดยตรง"},"table":{"title":"Average daily screen time (hours) by activity and age group","rows":[["Activity","15–18","19–24","25–40","41–60"],["Social media","3.1","2.8","1.9","1.2"],["Video streaming","2.2","2.5","1.8","1.6"],["Gaming","1.5","1.1","0.6","0.2"],["Work / study","1.4","2.9","3.6","2.2"],["Total","8.2","9.3","7.9","5.2"]]}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"Which statement best expresses the main idea of the article?","choices":["The hippocampus is the most important part of the brain for learning.","Students should stop studying late at night and study only in the morning.","REM sleep is more useful for learning than slow-wave sleep.","Sleep plays an active role in turning new information into lasting memories."],"answer":3,"explanation":{"en":"The article argues that sleep 'is part of the learning itself' and explains consolidation during sleep, so the main idea is that sleep plays an active role in turning new information into lasting memories. The other statements are details or overstatements.","th":"บทความเสนอว่าการนอน 'is part of the learning itself' และอธิบายกระบวนการ consolidation ระหว่างนอน ใจความสำคัญคือการนอนมีบทบาทในการเปลี่ยนข้อมูลใหม่ให้เป็นความจำที่คงทน ส่วนข้อความอื่นเป็นรายละเอียดหรือกล่าวเกินจริง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"m","skill":{"en":"Understanding reference","th":"การระบุสิ่งที่คำอ้างถึง"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"In paragraph 2, 'this state' refers to","choices":["the process of linking memories to existing knowledge","the period of deep sleep","the fragile form in which a new memory is first stored","the outer layer of the brain"],"answer":2,"explanation":{"en":"The sentence before says new information 'is stored in a fragile form, largely dependent on... the hippocampus', so 'this state' is the fragile form in which a new memory is first stored.","th":"ประโยคก่อนหน้าบอกว่าข้อมูลใหม่ 'is stored in a fragile form' ดังนั้น 'this state' หมายถึงสภาพเปราะบางที่ความจำใหม่ถูกเก็บไว้ในตอนแรก"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Making inferences","th":"การอนุมานจากข้อมูลในเรื่อง"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"Why does cutting the night short remove 'a disproportionate share of REM'?","choices":["Because REM sleep is concentrated in the later part of the night","Because REM sleep happens only during the first hour of sleep","Because students who sleep less dream more","Because the hippocampus stops working without REM sleep"],"answer":0,"explanation":{"en":"The article says REM 'becomes more frequent towards morning', so waking early removes much more REM than slow-wave sleep: REM sleep is concentrated in the later part of the night.","th":"บทความบอกว่า REM 'becomes more frequent towards morning' การตื่นเร็วจึงตัดช่วง REM ไปมากกว่าสัดส่วนปกติ เพราะ REM เกิดมากในช่วงท้ายของคืน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"e","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"The word 'durable' in the last paragraph is closest in meaning to","choices":["flexible","long-lasting","detailed","difficult"],"answer":1,"explanation":{"en":"Memories that are 'more durable' than those from cramming are ones that last longer, so 'durable' means long-lasting.","th":"ความจำที่ 'more durable' กว่าการอ่านอัดในครั้งเดียวคือความจำที่อยู่ได้นานกว่า 'durable' จึงแปลว่า long-lasting (คงทน)"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Understanding text organisation","th":"การเข้าใจโครงสร้างของบทความ"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"What is the main purpose of paragraph 5?","choices":["To argue that the research on sleep is unreliable","To give new evidence that sleep improves physical skills","To explain how to plan a revision timetable","To set limits on the argument and admit uncertainty in the research"],"answer":3,"explanation":{"en":"Paragraph 5 says sleep cannot replace study and that findings are 'not entirely uniform', but still maintains the main claim — it sets limits on the argument and admits uncertainty rather than rejecting the research.","th":"ย่อหน้าที่ 5 บอกว่าการนอนแทนการเรียนไม่ได้ และผลวิจัย 'not entirely uniform' แต่ยังยืนยันข้อเสนอหลัก จึงเป็นการจำกัดขอบเขตของข้อโต้แย้งและยอมรับความไม่แน่นอน ไม่ใช่การปฏิเสธงานวิจัย"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Identifying attitude and tone","th":"การระบุทัศนคติและน้ำเสียง"},"topic":{"en":"Article: sleep and memory","th":"บทความ: การนอนหลับกับความจำ"},"passage":"Why sleep is part of studying\n\nFor generations, students have treated sleep as the first thing to sacrifice before an exam. An all-night study session feels productive: the hours are there, the notes are open, and every page read seems like progress. Yet a growing body of research suggests that this trade-off is, in most cases, a poor one. Sleep is not simply a pause between periods of learning; it is part of the learning itself.\n\nTo understand why, it helps to know what happens to a new memory. When we first encounter information — a formula, a list of dates, the steps of a chemical reaction — it is stored in a fragile form, largely dependent on a small, seahorse-shaped region of the brain called the hippocampus. In this state, the memory is easily disrupted. Over the following hours and days, it is gradually reorganised and linked to existing knowledge in the cortex, the brain's outer layer. Scientists call this process consolidation, and a large share of it appears to happen while we sleep.\n\nDifferent stages of sleep seem to play different roles. During deep, slow-wave sleep, which dominates the first half of the night, recordings show the hippocampus \"replaying\" patterns of activity from the day, as if rehearsing what was learned. Rapid eye movement (REM) sleep, which becomes more frequent towards morning, has been linked to finding connections between ideas and to solving problems creatively. Cutting the night short therefore does not just reduce sleep by a fixed amount; it removes a disproportionate share of REM.\n\nThe evidence does not come only from brain recordings. In one common type of experiment, volunteers learn pairs of words in the evening and are tested the next morning. Those who sleep normally typically remember considerably more than those kept awake, even when both groups are given time to recover before the test. Similar results have been found for physical skills, such as typing a sequence on a keyboard: performance often improves after a night's sleep without any further practice.\n\nNone of this means that sleep can replace study. Consolidation can only strengthen what was learned in the first place, and a student who has never opened the textbook will not wake up knowing its contents. Nor are the findings entirely uniform; some studies have found smaller effects than others, and researchers still debate exactly how much each stage of sleep contributes. What the evidence does challenge is the assumption that time spent asleep is time taken away from learning.\n\nThe practical implications are fairly simple. Spreading study over several days, with sleep in between, tends to produce more durable memories than cramming the same number of hours into a single session. Reviewing difficult material in the evening, rather than first thing in the morning, may give it a better chance of being consolidated. And on the night before an exam, an extra hour of sleep is likely to be worth more than an extra hour of reading — however unconvincing that may feel at 2 a.m.","stem":"What does the writer suggest with the phrase 'however unconvincing that may feel at 2 a.m.'?","choices":["A tired student studying late may find the advice hard to accept, even though it is sound.","The advice applies only to students who study after 2 a.m.","Studying at 2 a.m. is the most effective time for reading.","The writer is not convinced by the research described."],"answer":0,"explanation":{"en":"The writer recommends sleeping instead of reading, then admits that a student still awake at 2 a.m. will probably not feel convinced — the advice may be hard to accept even though it is sound.","th":"ผู้เขียนแนะนำให้นอนแทนการอ่านเพิ่ม แล้วยอมรับว่านักเรียนที่ยังอ่านตอนตีสองอาจไม่รู้สึกเชื่อ คำแนะนำจึงอาจยอมรับได้ยากแม้จะถูกต้อง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"m","skill":{"en":"Identifying the writer's purpose","th":"การระบุจุดประสงค์ของผู้เขียน"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"What is the writer's main purpose?","choices":["To explain why cities are hotter and to evaluate ways of cooling them","To criticise urban planners for ignoring the heat problem","To compare the climate of Bangkok with that of other cities","To persuade readers to plant trees in their own gardens"],"answer":0,"explanation":{"en":"The article first explains the causes and effects of urban heat islands and then weighs remedies (trees, cool roofs, paving, regulations), so it explains why cities are hotter and evaluates ways of cooling them.","th":"บทความอธิบายสาเหตุและผลกระทบของเกาะความร้อนในเมือง แล้วประเมินวิธีแก้ (ต้นไม้ หลังคาเย็น ทางเท้าซึมน้ำ กฎหมายอาคาร) จุดประสงค์จึงเป็นการอธิบายและประเมินวิธีทำให้เมืองเย็นลง"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"m","skill":{"en":"Identifying information that is not stated","th":"การระบุข้อมูลที่ไม่ได้กล่าวถึง"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"Which of the following is NOT given as a cause of the urban heat island effect?","choices":["Air pollution trapping heat above the city","Less evaporation because of fewer plants","Hard surfaces releasing stored heat at night","Buildings reducing the flow of wind"],"answer":0,"explanation":{"en":"Paragraph 2 lists stored heat in hard surfaces, buildings blocking wind, heat from machines and the loss of evaporation. Air pollution trapping heat above the city is never mentioned.","th":"ย่อหน้าที่ 2 กล่าวถึงพื้นผิวแข็งที่ปล่อยความร้อน อาคารบังลม ความร้อนจากเครื่องจักร และการระเหยของน้ำที่ลดลง แต่ไม่ได้กล่าวถึงมลพิษทางอากาศที่กักความร้อนไว้"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Vocabulary in context","th":"การเดาความหมายคำศัพท์จากบริบท"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"In paragraph 3, a 'cruel feedback loop' is","choices":["a cycle of hot days followed by cool nights","a policy that punishes people for using air conditioners","a system that sends information about temperatures to residents","a situation in which the response to heat makes the heat worse"],"answer":3,"explanation":{"en":"As the city warms, people use more air conditioners, which 'pump heat outside' and burn more fossil fuels — the response to heat makes the heat worse, which is why it is 'cruel'.","th":"เมื่อเมืองร้อนขึ้น คนเปิดแอร์มากขึ้น แอร์ 'pump heat outside' และใช้ไฟจากเชื้อเพลิงฟอสซิลมากขึ้น การรับมือกับความร้อนจึงทำให้ร้อนยิ่งขึ้น เป็นวงจรที่ 'cruel'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"e","skill":{"en":"Understanding reference","th":"การระบุสิ่งที่คำอ้างถึง"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"In paragraph 4, 'their own area' refers to the area of","choices":["streets","trees","parks","studies"],"answer":2,"explanation":{"en":"The sentence is 'Parks can cool not only their own area but also streets...', so 'their' refers to parks.","th":"ประโยคคือ 'Parks can cool not only their own area but also streets...' คำว่า 'their' จึงหมายถึง parks (สวนสาธารณะ)"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"m","skill":{"en":"Finding specific information","th":"การหาข้อมูลเฉพาะ"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"According to the article, why do many trees planted in publicity campaigns die?","choices":["They are planted too close to air conditioners.","No one takes long-term responsibility for looking after them.","Their roots are cut to protect underground cables.","They are always the wrong species for the city."],"answer":1,"explanation":{"en":"The article says they 'die within a few years because no one is responsible for maintaining them' — no one takes long-term responsibility for looking after them.","th":"บทความบอกว่าต้นไม้เหล่านั้น 'die within a few years because no one is responsible for maintaining them' คือไม่มีใครรับผิดชอบดูแลในระยะยาว"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"reading-article","difficulty":"h","skill":{"en":"Identifying attitude and tone","th":"การระบุทัศนคติและน้ำเสียง"},"topic":{"en":"Article: urban heat islands","th":"บทความ: เกาะความร้อนในเมือง"},"passage":"Cooling the city\n\nOn a hot afternoon in April, the difference can be felt simply by crossing a road. On one side, a car park of dark asphalt radiates heat back at passers-by; on the other, under a row of rain trees, the air is noticeably cooler. Multiply that small contrast across an entire city and you have what scientists call the urban heat island effect: the tendency of built-up areas to be several degrees warmer than the countryside around them.\n\nThe causes are well understood. Concrete, asphalt and brick absorb sunlight during the day and release it slowly at night, so cities cool down far less after sunset than rural areas do. Buildings block the wind that would otherwise carry heat away. Air conditioners, vehicles and factories add heat of their own. And because cities have replaced soil and vegetation with hard surfaces, they lose much of the cooling that comes from water evaporating from leaves and ground — the same process that cools our skin when we sweat.\n\nFor tropical cities such as Bangkok, the consequences are serious. Night-time temperatures matter particularly for health, since the body needs cooler hours to recover from daytime heat. Older people, outdoor workers and those without air conditioning are most at risk. There is also a cruel feedback loop: as the city warms, more people switch on air conditioners, which pump heat outside and increase demand for electricity, much of it still generated by burning fossil fuels.\n\nOf the many proposed remedies, trees are among the most popular, and with good reason. A mature tree shades the ground beneath it and, through its leaves, releases large quantities of water vapour. Studies in several cities have measured surface temperatures under tree canopies that are more than ten degrees lower than on nearby exposed pavements. Parks can cool not only their own area but also streets some distance downwind.\n\nYet planting trees is not as straightforward as it sounds. In dense neighbourhoods there is often simply no room: pavements are narrow, and underground space is occupied by pipes and cables that roots can damage. Young trees need years of watering and care before they provide meaningful shade, and many planted in publicity campaigns die within a few years because no one is responsible for maintaining them. Choosing the wrong species can create new problems, from falling branches in storms to roots that lift pavements.\n\nFor these reasons, urban planners increasingly argue that trees should be one part of a broader strategy. Light-coloured \"cool roofs\" reflect sunlight instead of absorbing it. Permeable paving lets rainwater soak into the ground, where it can later evaporate. Building regulations can require shaded walkways or limit the share of a plot that may be covered with hard surfaces. None of these measures is dramatic on its own. Combined, and sustained over decades, they could make the difference between a city that is merely hot and one that is dangerously so.","stem":"Which best describes the writer's view of trees as a solution?","choices":["Valuable, but not enough on their own","Overrated and largely ineffective","Too expensive for tropical cities","The only solution that really works"],"answer":0,"explanation":{"en":"The writer says trees are popular 'with good reason' but that planting them 'is not as straightforward as it sounds' and they should be 'one part of a broader strategy' — valuable, but not enough on their own.","th":"ผู้เขียนบอกว่าต้นไม้ได้รับความนิยม 'with good reason' แต่การปลูก 'is not as straightforward as it sounds' และควรเป็น 'one part of a broader strategy' จึงมีคุณค่าแต่ไม่เพียงพอหากใช้วิธีเดียว"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"e","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Formal email: requesting an extension","th":"อีเมลแบบทางการ: ขอขยายเวลาส่งงาน"},"passage":"Read the email and choose the best option for each gap.\n\nDear Dr Somchai,\n\nI am writing to (1) ______ for the research essay in ENG 214, which is due this Friday.\n\nLast week my grandfather was admitted to hospital, and I have been travelling to Nakhon Sawan to help my family care for him. (2) ______ I have completed the research and about half of the draft, but I am concerned that the final sections would be rushed if I submitted it on time.\n\n(3) ______ would be extremely helpful. I would of course be happy to provide a letter from the hospital (4) ______.\n\n(5) ______ Thank you for considering my request.\n\nYours sincerely,\nNicha Boonmee (Student ID 6612345)","stem":"Which choice best completes gap (1)?","choices":["ask whether the essay topic could be changed","request a short extension of the deadline","inform you that I will not be submitting the essay","let you know that I have already submitted the essay"],"answer":1,"explanation":{"en":"The rest of the email explains why she needs more time and ends with 'my request', so she is writing to request a short extension of the deadline.","th":"เนื้อหาที่เหลืออธิบายว่าทำไมต้องการเวลาเพิ่ม และปิดท้ายด้วย 'my request' จึงเป็นการเขียนเพื่อ request a short extension of the deadline (ขอขยายเวลาส่ง)"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Formal email: requesting an extension","th":"อีเมลแบบทางการ: ขอขยายเวลาส่งงาน"},"passage":"Read the email and choose the best option for each gap.\n\nDear Dr Somchai,\n\nI am writing to (1) ______ for the research essay in ENG 214, which is due this Friday.\n\nLast week my grandfather was admitted to hospital, and I have been travelling to Nakhon Sawan to help my family care for him. (2) ______ I have completed the research and about half of the draft, but I am concerned that the final sections would be rushed if I submitted it on time.\n\n(3) ______ would be extremely helpful. I would of course be happy to provide a letter from the hospital (4) ______.\n\n(5) ______ Thank you for considering my request.\n\nYours sincerely,\nNicha Boonmee (Student ID 6612345)","stem":"Which choice best completes gap (2)?","choices":["As a result, I have had far less time for my studies than I had planned.","Fortunately, this has given me more time to work on the essay.","However, my grandfather used to be a teacher himself.","In addition, the hospital has excellent facilities."],"answer":0,"explanation":{"en":"Caring for her grandfather leads to a consequence relevant to the essay, so 'As a result, I have had far less time for my studies than I had planned.' links the two paragraphs. 'Fortunately... more time' contradicts the request, and the other two are irrelevant.","th":"การไปดูแลคุณตาส่งผลต่อการเขียนงาน จึงต้องใช้ 'As a result, I have had far less time for my studies than I had planned.' ส่วน 'Fortunately... more time' ขัดกับการขอขยายเวลา และอีกสองประโยคไม่เกี่ยวกับประเด็น"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Formal email: requesting an extension","th":"อีเมลแบบทางการ: ขอขยายเวลาส่งงาน"},"passage":"Read the email and choose the best option for each gap.\n\nDear Dr Somchai,\n\nI am writing to (1) ______ for the research essay in ENG 214, which is due this Friday.\n\nLast week my grandfather was admitted to hospital, and I have been travelling to Nakhon Sawan to help my family care for him. (2) ______ I have completed the research and about half of the draft, but I am concerned that the final sections would be rushed if I submitted it on time.\n\n(3) ______ would be extremely helpful. I would of course be happy to provide a letter from the hospital (4) ______.\n\n(5) ______ Thank you for considering my request.\n\nYours sincerely,\nNicha Boonmee (Student ID 6612345)","stem":"Which choice best completes gap (3)?","choices":["If possible, an extension until next Friday","A meeting with my grandfather's doctor","Your decision to cancel the essay","A lower grade for the essay"],"answer":0,"explanation":{"en":"The subject of 'would be extremely helpful' must be what she is asking for: 'If possible, an extension until next Friday'. Asking for a lower grade or cancellation does not make sense.","th":"ประธานของ 'would be extremely helpful' ต้องเป็นสิ่งที่เธอขอ คือ 'If possible, an extension until next Friday' การขอคะแนนต่ำลงหรือยกเลิกงานไม่สมเหตุสมผล"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Register in written texts","th":"การใช้ระดับภาษาในงานเขียน"},"topic":{"en":"Formal email: requesting an extension","th":"อีเมลแบบทางการ: ขอขยายเวลาส่งงาน"},"passage":"Read the email and choose the best option for each gap.\n\nDear Dr Somchai,\n\nI am writing to (1) ______ for the research essay in ENG 214, which is due this Friday.\n\nLast week my grandfather was admitted to hospital, and I have been travelling to Nakhon Sawan to help my family care for him. (2) ______ I have completed the research and about half of the draft, but I am concerned that the final sections would be rushed if I submitted it on time.\n\n(3) ______ would be extremely helpful. I would of course be happy to provide a letter from the hospital (4) ______.\n\n(5) ______ Thank you for considering my request.\n\nYours sincerely,\nNicha Boonmee (Student ID 6612345)","stem":"Which choice best completes gap (4)?","choices":["whether you want it or not","so that you have to accept","if that would be helpful","if you don't believe me"],"answer":2,"explanation":{"en":"A polite, formal offer to a lecturer is 'if that would be helpful'. The other phrases sound suspicious, demanding or rude.","th":"การเสนอเอกสารอย่างสุภาพต่ออาจารย์ใช้ 'if that would be helpful' ส่วนวลีอื่นฟังดูกล่าวหา บังคับ หรือไม่สุภาพ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Register in written texts","th":"การใช้ระดับภาษาในงานเขียน"},"topic":{"en":"Formal email: requesting an extension","th":"อีเมลแบบทางการ: ขอขยายเวลาส่งงาน"},"passage":"Read the email and choose the best option for each gap.\n\nDear Dr Somchai,\n\nI am writing to (1) ______ for the research essay in ENG 214, which is due this Friday.\n\nLast week my grandfather was admitted to hospital, and I have been travelling to Nakhon Sawan to help my family care for him. (2) ______ I have completed the research and about half of the draft, but I am concerned that the final sections would be rushed if I submitted it on time.\n\n(3) ______ would be extremely helpful. I would of course be happy to provide a letter from the hospital (4) ______.\n\n(5) ______ Thank you for considering my request.\n\nYours sincerely,\nNicha Boonmee (Student ID 6612345)","stem":"Which choice best completes gap (5)?","choices":["I hope you will not be too strict with me this time.","My friends also need more time, so please consider them too.","I am sure you will agree that this is completely fair.","Please let me know if you would like me to send the completed sections in the meantime."],"answer":3,"explanation":{"en":"A polite closing that offers something helpful suits a formal request: 'Please let me know if you would like me to send the completed sections in the meantime.' The others are presumptuous, irrelevant or pressure the lecturer.","th":"การปิดท้ายอีเมลขอร้องอย่างสุภาพควรเสนอสิ่งที่เป็นประโยชน์ จึงใช้ 'Please let me know if you would like me to send the completed sections in the meantime.' ประโยคอื่นถือวิสาสะ ไม่เกี่ยว หรือกดดันอาจารย์"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Expository text: plastic recycling","th":"ข้อความเชิงอธิบาย: การรีไซเคิลพลาสติก"},"passage":"Read the passage and choose the best option for each gap.\n\nMany people assume that putting a plastic bottle in a recycling bin guarantees that it will become a new product. (6) ______ In practice, only a small fraction of all the plastic ever produced has been recycled. One reason is that there are many different types of plastic, (7) ______. Food waste and mixed materials, such as labels glued to containers, add further costs. (8) ______, a large proportion of collected plastic is burned, buried or shipped abroad. Some experts therefore argue that recycling has received too much attention (9) ______. If fewer single-use items were produced in the first place, they say, there would be less waste to manage. (10) ______","stem":"Which choice best completes gap (6)?","choices":["The reality is considerably less encouraging.","Recycling bins are usually painted blue.","As a result, plastic waste has almost disappeared.","This is exactly what happens in most countries."],"answer":0,"explanation":{"en":"The next sentence ('In practice, only a small fraction...') contrasts with the assumption, so the gap must signal that contrast: 'The reality is considerably less encouraging.'","th":"ประโยคถัดไป ('In practice, only a small fraction...') ขัดแย้งกับความเชื่อในประโยคแรก ช่องว่างจึงต้องเปิดประเด็นแย้ง: 'The reality is considerably less encouraging.'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Expository text: plastic recycling","th":"ข้อความเชิงอธิบาย: การรีไซเคิลพลาสติก"},"passage":"Read the passage and choose the best option for each gap.\n\nMany people assume that putting a plastic bottle in a recycling bin guarantees that it will become a new product. (6) ______ In practice, only a small fraction of all the plastic ever produced has been recycled. One reason is that there are many different types of plastic, (7) ______. Food waste and mixed materials, such as labels glued to containers, add further costs. (8) ______, a large proportion of collected plastic is burned, buried or shipped abroad. Some experts therefore argue that recycling has received too much attention (9) ______. If fewer single-use items were produced in the first place, they say, there would be less waste to manage. (10) ______","stem":"Which choice best completes gap (7)?","choices":["and many of them cannot be processed together","which makes recycling much simpler","although all of them melt at the same temperature","most of which are made in Asia"],"answer":0,"explanation":{"en":"The sentence gives 'one reason' recycling is difficult, so it needs 'and many of them cannot be processed together'. 'Much simpler' contradicts the point, and the others do not explain a difficulty.","th":"ประโยคนี้ให้ 'one reason' ที่การรีไซเคิลทำได้ยาก จึงต้องเป็น 'and many of them cannot be processed together' ส่วน 'much simpler' ขัดกับประเด็น และอีกสองตัวเลือกไม่ได้อธิบายความยุ่งยาก"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Expository text: plastic recycling","th":"ข้อความเชิงอธิบาย: การรีไซเคิลพลาสติก"},"passage":"Read the passage and choose the best option for each gap.\n\nMany people assume that putting a plastic bottle in a recycling bin guarantees that it will become a new product. (6) ______ In practice, only a small fraction of all the plastic ever produced has been recycled. One reason is that there are many different types of plastic, (7) ______. Food waste and mixed materials, such as labels glued to containers, add further costs. (8) ______, a large proportion of collected plastic is burned, buried or shipped abroad. Some experts therefore argue that recycling has received too much attention (9) ______. If fewer single-use items were produced in the first place, they say, there would be less waste to manage. (10) ______","stem":"Which choice best completes gap (8)?","choices":["In contrast to these difficulties","For example","Even though these costs have been removed","Because sorting and cleaning are so expensive"],"answer":3,"explanation":{"en":"The costs of sorting and cleaning explain why much plastic is burned or buried, so a cause is needed: 'Because sorting and cleaning are so expensive'. 'Even though... removed' contradicts the costs just mentioned, and the other connectors give the wrong relationship.","th":"ค่าใช้จ่ายในการคัดแยกและทำความสะอาดเป็นสาเหตุที่พลาสติกจำนวนมากถูกเผาหรือฝัง จึงต้องใช้ 'Because sorting and cleaning are so expensive' ส่วน 'Even though... removed' ขัดกับค่าใช้จ่ายที่เพิ่งกล่าว และตัวเชื่อมอื่นแสดงความสัมพันธ์ผิด"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Expository text: plastic recycling","th":"ข้อความเชิงอธิบาย: การรีไซเคิลพลาสติก"},"passage":"Read the passage and choose the best option for each gap.\n\nMany people assume that putting a plastic bottle in a recycling bin guarantees that it will become a new product. (6) ______ In practice, only a small fraction of all the plastic ever produced has been recycled. One reason is that there are many different types of plastic, (7) ______. Food waste and mixed materials, such as labels glued to containers, add further costs. (8) ______, a large proportion of collected plastic is burned, buried or shipped abroad. Some experts therefore argue that recycling has received too much attention (9) ______. If fewer single-use items were produced in the first place, they say, there would be less waste to manage. (10) ______","stem":"Which choice best completes gap (9)?","choices":["instead of burning more plastic","because it is far too easy to do","since nobody recycles anything at all","compared with reducing the amount of plastic used"],"answer":3,"explanation":{"en":"The next sentence argues for producing fewer single-use items, so experts think recycling gets too much attention 'compared with reducing the amount of plastic used'. Burning more plastic is not what they recommend.","th":"ประโยคถัดมาเสนอให้ผลิตสินค้าใช้ครั้งเดียวให้น้อยลง ผู้เชี่ยวชาญจึงเห็นว่าการรีไซเคิลได้รับความสนใจมากเกินไป 'compared with reducing the amount of plastic used' ไม่ได้แนะนำให้เผาพลาสติกเพิ่ม"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Expository text: plastic recycling","th":"ข้อความเชิงอธิบาย: การรีไซเคิลพลาสติก"},"passage":"Read the passage and choose the best option for each gap.\n\nMany people assume that putting a plastic bottle in a recycling bin guarantees that it will become a new product. (6) ______ In practice, only a small fraction of all the plastic ever produced has been recycled. One reason is that there are many different types of plastic, (7) ______. Food waste and mixed materials, such as labels glued to containers, add further costs. (8) ______, a large proportion of collected plastic is burned, buried or shipped abroad. Some experts therefore argue that recycling has received too much attention (9) ______. If fewer single-use items were produced in the first place, they say, there would be less waste to manage. (10) ______","stem":"Which choice best completes gap (10)?","choices":["However, nobody knows exactly what plastic is made from.","Single-use plastics should therefore be produced in greater quantities.","In this view, recycling should be the last option rather than the first.","This is why experts recommend recycling as many bottles as possible."],"answer":2,"explanation":{"en":"The final sentence should sum up the experts' argument that reducing comes first: 'In this view, recycling should be the last option rather than the first.' The other sentences contradict or ignore that argument.","th":"ประโยคสุดท้ายควรสรุปความเห็นของผู้เชี่ยวชาญว่าการลดการใช้มาก่อน: 'In this view, recycling should be the last option rather than the first.' ประโยคอื่นขัดแย้งหรือไม่เกี่ยวกับข้อโต้แย้งนี้"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"e","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Advice text: giving presentations","th":"ข้อความแนะนำ: การนำเสนองาน"},"passage":"Read the advice text and choose the best option for each gap.\n\nMost students have sat through a presentation in which the speaker simply read the slides aloud. (11) ______ The first step towards avoiding this is to think about your audience before you open any software. What do they already know, and (12) ______? Once you have answered these questions, plan your talk around no more than three main points. (13) ______, it is far better to explain a few ideas clearly than to rush through many. Slides should support what you say, not repeat it: a single image or a short phrase is often more effective (14) ______. Finally, rehearse out loud, ideally in front of a friend. (15) ______","stem":"Which choice best completes gap (11)?","choices":["Reading aloud is a skill that all teachers recommend.","Such presentations are usually the most memorable.","It is an experience that few audiences enjoy.","This is the reason slides were invented."],"answer":2,"explanation":{"en":"The next sentence talks about 'avoiding this', so the gap must present slide-reading as negative: 'It is an experience that few audiences enjoy.'","th":"ประโยคถัดไปพูดถึง 'avoiding this' ช่องว่างจึงต้องบอกว่าการอ่านสไลด์เป็นเรื่องไม่ดี: 'It is an experience that few audiences enjoy.'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Advice text: giving presentations","th":"ข้อความแนะนำ: การนำเสนองาน"},"passage":"Read the advice text and choose the best option for each gap.\n\nMost students have sat through a presentation in which the speaker simply read the slides aloud. (11) ______ The first step towards avoiding this is to think about your audience before you open any software. What do they already know, and (12) ______? Once you have answered these questions, plan your talk around no more than three main points. (13) ______, it is far better to explain a few ideas clearly than to rush through many. Slides should support what you say, not repeat it: a single image or a short phrase is often more effective (14) ______. Finally, rehearse out loud, ideally in front of a friend. (15) ______","stem":"Which choice best completes gap (12)?","choices":["why did they choose to sit there","what time does the room close","how many slides does your software allow","what do you want them to remember afterwards"],"answer":3,"explanation":{"en":"The question is about the audience and leads to planning 'three main points', so it must be 'what do you want them to remember afterwards'. The others are not about the audience's needs.","th":"คำถามนี้เกี่ยวกับผู้ฟังและนำไปสู่การวางแผน 'three main points' จึงต้องเป็น 'what do you want them to remember afterwards' ตัวเลือกอื่นไม่เกี่ยวกับสิ่งที่ผู้ฟังต้องการ"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Advice text: giving presentations","th":"ข้อความแนะนำ: การนำเสนองาน"},"passage":"Read the advice text and choose the best option for each gap.\n\nMost students have sat through a presentation in which the speaker simply read the slides aloud. (11) ______ The first step towards avoiding this is to think about your audience before you open any software. What do they already know, and (12) ______? Once you have answered these questions, plan your talk around no more than three main points. (13) ______, it is far better to explain a few ideas clearly than to rush through many. Slides should support what you say, not repeat it: a single image or a short phrase is often more effective (14) ______. Finally, rehearse out loud, ideally in front of a friend. (15) ______","stem":"Which choice best completes gap (13)?","choices":["In the same way as reading slides","Despite having plenty of time","Unlike a good speaker","With only limited time available"],"answer":3,"explanation":{"en":"Limiting the talk to three points is justified by time pressure: 'With only limited time available, it is far better to explain a few ideas clearly...' 'Plenty of time' would not justify fewer points.","th":"การจำกัดไว้สามประเด็นมีเหตุผลจากเวลาที่จำกัด: 'With only limited time available, it is far better to explain a few ideas clearly...' ถ้ามีเวลามากก็ไม่จำเป็นต้องลดประเด็น"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"m","skill":{"en":"Cohesion: linking ideas logically","th":"การเชื่อมโยงความคิดอย่างมีเหตุผล"},"topic":{"en":"Advice text: giving presentations","th":"ข้อความแนะนำ: การนำเสนองาน"},"passage":"Read the advice text and choose the best option for each gap.\n\nMost students have sat through a presentation in which the speaker simply read the slides aloud. (11) ______ The first step towards avoiding this is to think about your audience before you open any software. What do they already know, and (12) ______? Once you have answered these questions, plan your talk around no more than three main points. (13) ______, it is far better to explain a few ideas clearly than to rush through many. Slides should support what you say, not repeat it: a single image or a short phrase is often more effective (14) ______. Finally, rehearse out loud, ideally in front of a friend. (15) ______","stem":"Which choice best completes gap (14)?","choices":["than a paragraph of text","when it is printed very small","than speaking at all","unless the audience can read"],"answer":0,"explanation":{"en":"'More effective' needs a comparison with 'than', and the point is that slides should not repeat what you say, so the comparison is 'than a paragraph of text'.","th":"'More effective' ต้องเปรียบเทียบด้วย 'than' และประเด็นคือสไลด์ไม่ควรมีข้อความซ้ำกับที่พูด จึงเป็น 'than a paragraph of text'"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"text-completion","difficulty":"h","skill":{"en":"Coherence: choosing content that fits the meaning","th":"การเลือกเนื้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Advice text: giving presentations","th":"ข้อความแนะนำ: การนำเสนองาน"},"passage":"Read the advice text and choose the best option for each gap.\n\nMost students have sat through a presentation in which the speaker simply read the slides aloud. (11) ______ The first step towards avoiding this is to think about your audience before you open any software. What do they already know, and (12) ______? Once you have answered these questions, plan your talk around no more than three main points. (13) ______, it is far better to explain a few ideas clearly than to rush through many. Slides should support what you say, not repeat it: a single image or a short phrase is often more effective (14) ______. Finally, rehearse out loud, ideally in front of a friend. (15) ______","stem":"Which choice best completes gap (15)?","choices":["You will quickly discover which parts sound unclear or take too long.","Rehearsing silently, however, is always more effective.","That way, you will not need to prepare anything else.","Your friend can then give the presentation for you."],"answer":0,"explanation":{"en":"The last sentence should give the benefit of rehearsing aloud: 'You will quickly discover which parts sound unclear or take too long.' 'Rehearsing silently... more effective' contradicts the advice, and the others are illogical.","th":"ประโยคสุดท้ายควรบอกประโยชน์ของการซ้อมออกเสียง: 'You will quickly discover which parts sound unclear or take too long.' ส่วนการบอกว่าซ้อมในใจดีกว่าขัดกับคำแนะนำ และตัวเลือกอื่นไม่สมเหตุผล"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"paragraph","difficulty":"e","skill":{"en":"Organising sentences into a logical paragraph","th":"การเรียงประโยคเป็นย่อหน้าอย่างมีลำดับ"},"topic":{"en":"Paragraph organization: process","th":"เรียงประโยค: ขั้นตอน"},"passage":"[1] When you have finished your journey, return the bike to any docking station.\n[2] Using the city's bike-share system is straightforward once you have registered.\n[3] Your account will be charged automatically according to how long you used the bike.\n[4] First, download the app and link it to a payment card.\n[5] Then scan the QR code on any available bike to unlock it.","stem":"The sentences above are in jumbled order. Which order makes the most logical paragraph?","choices":["[2] – [4] – [5] – [1] – [3]","[4] – [5] – [2] – [1] – [3]","[2] – [5] – [4] – [1] – [3]","[2] – [4] – [5] – [3] – [1]"],"answer":0,"explanation":{"en":"[2] – [4] – [5] – [1] – [3]: the topic sentence ('straightforward once you have registered') comes first, then the steps in sequence marked by 'First', 'Then' and 'When you have finished', and finally the automatic charge after the bike is returned.","th":"[2] – [4] – [5] – [1] – [3]: เริ่มด้วยประโยคใจความหลัก ('straightforward once you have registered') แล้วเรียงขั้นตอนตามคำบอกลำดับ 'First', 'Then', 'When you have finished' และจบด้วยการตัดเงินอัตโนมัติหลังคืนจักรยาน"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"paragraph","difficulty":"m","skill":{"en":"Organising sentences into a logical paragraph","th":"การเรียงประโยคเป็นย่อหน้าอย่างมีลำดับ"},"topic":{"en":"Paragraph organization: narrative","th":"เรียงประโยค: การเล่าเรื่อง"},"passage":"[1] Around the mould, however, the bacteria had been destroyed.\n[2] It was more than a decade, though, before other scientists found a way to produce this substance in large quantities.\n[3] In 1928, Alexander Fleming returned from a holiday to find something unusual in his laboratory.\n[4] He realised that the mould must be producing a substance that killed them.\n[5] A mould had grown on one of the dishes in which he was growing bacteria.","stem":"The sentences above are in jumbled order. Which order makes the most logical paragraph?","choices":["[3] – [1] – [5] – [4] – [2]","[3] – [5] – [4] – [1] – [2]","[5] – [3] – [1] – [4] – [2]","[3] – [5] – [1] – [4] – [2]"],"answer":3,"explanation":{"en":"[3] – [5] – [1] – [4] – [2]: the date and 'something unusual' open the story; 'A mould' explains what he found; 'however' contrasts the mould with the destroyed bacteria; 'He realised' gives his conclusion; 'this substance' and 'more than a decade' close the paragraph.","th":"[3] – [5] – [1] – [4] – [2]: ปีและ 'something unusual' เปิดเรื่อง ตามด้วยเชื้อราที่พบ คำว่า 'however' แสดงว่าแบคทีเรียรอบเชื้อราถูกทำลาย 'He realised' คือข้อสรุปของเขา และ 'this substance' กับ 'more than a decade' ปิดย่อหน้า"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"paragraph","difficulty":"m","skill":{"en":"Organising sentences into a logical paragraph","th":"การเรียงประโยคเป็นย่อหน้าอย่างมีลำดับ"},"topic":{"en":"Paragraph organization: argument","th":"เรียงประโยค: การเสนอข้อโต้แย้ง"},"passage":"[1] Early results suggest that both views contain some truth.\n[2] Supporters claim that employees who work fewer days are more focused and less likely to burn out.\n[3] Productivity rose in many of the trial firms, but some had to hire extra staff to maintain their service.\n[4] Several companies have recently experimented with a four-day working week.\n[5] Critics, on the other hand, worry that customers will suffer if offices close for an extra day.","stem":"The sentences above are in jumbled order. Which order makes the most logical paragraph?","choices":["[4] – [2] – [5] – [3] – [1]","[4] – [5] – [2] – [1] – [3]","[1] – [4] – [2] – [5] – [3]","[4] – [2] – [5] – [1] – [3]"],"answer":3,"explanation":{"en":"[4] – [2] – [5] – [1] – [3]: the topic is introduced, then 'Supporters' and 'Critics, on the other hand' give the two sides; 'both views' must follow both sides, and the final sentence gives evidence for each view.","th":"[4] – [2] – [5] – [1] – [3]: เริ่มด้วยการแนะนำหัวข้อ ตามด้วยฝ่าย 'Supporters' และ 'Critics, on the other hand' ประโยค 'both views' ต้องมาหลังจากกล่าวถึงทั้งสองฝ่าย และประโยคสุดท้ายให้หลักฐานสนับสนุนแต่ละฝ่าย"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"paragraph","difficulty":"h","skill":{"en":"Organising sentences into a logical paragraph","th":"การเรียงประโยคเป็นย่อหน้าอย่างมีลำดับ"},"topic":{"en":"Paragraph organization: cause and effect","th":"เรียงประโยค: เหตุและผล"},"passage":"[1] When the water becomes too warm, however, the coral expels the algae.\n[2] Coral reefs are built by tiny animals that live in partnership with algae.\n[3] If temperatures do not return to normal within a few weeks, the coral may starve and die.\n[4] Without them, the coral turns white, a process known as bleaching.\n[5] The algae provide the coral with food and give it its bright colours.","stem":"The sentences above are in jumbled order. Which order makes the most logical paragraph?","choices":["[2] – [5] – [4] – [1] – [3]","[2] – [5] – [1] – [4] – [3]","[5] – [2] – [1] – [4] – [3]","[2] – [1] – [5] – [4] – [3]"],"answer":1,"explanation":{"en":"[2] – [5] – [1] – [4] – [3]: the partnership with 'algae' is introduced; 'The algae' explains their role (food and colour); 'however' introduces the problem of warm water; 'Without them' refers back to the expelled algae; the final sentence gives the long-term result.","th":"[2] – [5] – [1] – [4] – [3]: เริ่มจากความสัมพันธ์กับ 'algae' ตามด้วย 'The algae' อธิบายบทบาท (อาหารและสีสัน) คำว่า 'however' นำปัญหาน้ำอุ่น 'Without them' อ้างถึงสาหร่ายที่ถูกขับออก และประโยคสุดท้ายเป็นผลระยะยาว"}},{"kind":"m1","program":"alevel","subject":"eng","lang":"en","format":"mcq","part":"paragraph","difficulty":"h","skill":{"en":"Organising sentences into a logical paragraph","th":"การเรียงประโยคเป็นย่อหน้าอย่างมีลำดับ"},"topic":{"en":"Paragraph organization: comparison","th":"เรียงประโยค: การเปรียบเทียบ"},"passage":"[1] Many readers therefore end up owning both, choosing whichever suits the situation.\n[2] They also allow readers to change the font size, a real benefit for people with poor eyesight.\n[3] Choosing between printed books and e-books depends largely on how a reader uses them.\n[4] Printed books, by contrast, never need charging and are easier to lend to friends.\n[5] E-readers are light and can store thousands of titles, which makes them ideal for travel.","stem":"The sentences above are in jumbled order. Which order makes the most logical paragraph?","choices":["[3] – [5] – [4] – [2] – [1]","[3] – [4] – [5] – [2] – [1]","[3] – [2] – [5] – [4] – [1]","[3] – [5] – [2] – [4] – [1]"],"answer":3,"explanation":{"en":"[3] – [5] – [2] – [4] – [1]: the general statement comes first; 'E-readers' must come before 'They also' (which adds a second e-reader benefit); 'by contrast' turns to printed books; 'therefore... owning both' concludes.","th":"[3] – [5] – [2] – [4] – [1]: ประโยคกว้าง ๆ มาก่อน 'E-readers' ต้องมาก่อน 'They also' (ข้อดีข้อที่สองของเครื่องอ่าน) 'by contrast' เปลี่ยนไปพูดถึงหนังสือเล่ม และ 'therefore... owning both' เป็นข้อสรุป"}}]};
